import type { FastifyInstance } from 'fastify'
import { crmRealtimeConfig } from '../config/crm-realtime.js'
import type { PollingMarkerConfig } from '../observability/egress-baseline/types.js'

export interface CrmUiRoutesOptions { readonly pollingMarker: PollingMarkerConfig }

export async function crmUiRoutes(app: FastifyInstance, options: CrmUiRoutesOptions) {
  const crmHtml = renderCrmHtml(options)
  app.get('/crm', async (_request, reply) => {
    return reply.type('text/html').send(crmHtml)
  })
}

const weeklyScheduleDays = [
  { key: 'monday', label: 'Lunes', dayOfWeek: 1, weekend: false },
  { key: 'tuesday', label: 'Martes', dayOfWeek: 2, weekend: false },
  { key: 'wednesday', label: 'Mi&eacute;rcoles', dayOfWeek: 3, weekend: false },
  { key: 'thursday', label: 'Jueves', dayOfWeek: 4, weekend: false },
  { key: 'friday', label: 'Viernes', dayOfWeek: 5, weekend: false },
  { key: 'saturday', label: 'S&aacute;bado', dayOfWeek: 6, weekend: true },
  { key: 'sunday', label: 'Domingo', dayOfWeek: 0, weekend: true }
] as const

export function weeklyScheduleRows(input: {
  prefix: string
  rowClass: string
  weekdayEnd: string
  weekendEnd: string
}) {
  return weeklyScheduleDays.map((day) => {
    const endTime = day.weekend ? input.weekendEnd : input.weekdayEnd
    return `<div class="${input.rowClass}" data-weekly-schedule-day="${day.dayOfWeek}">
      <label><input id="${input.prefix}-${day.key}-enabled" type="checkbox"> ${day.label}</label>
      <div class="weekly-schedule-day-content">
        <div class="weekly-schedule-ranges">
          <div class="weekly-schedule-range">
            <input class="field" id="${input.prefix}-${day.key}-start" type="time" value="09:00" aria-label="Hora de inicio">
            <span class="schedule-separator">a</span>
            <input class="field" id="${input.prefix}-${day.key}-end" type="time" value="${endTime}" aria-label="Hora de cierre">
            <button class="weekly-schedule-remove" type="button" aria-label="Eliminar horario">&times;</button>
          </div>
        </div>
        <button class="weekly-schedule-add" type="button" data-weekly-schedule-add>+ Agregar otro horario</button>
        <span class="weekly-schedule-closed">Cerrado</span>
      </div>
    </div>`
  }).join('')
}

export function filterAssignedServices<T extends { id: string }>(
  professional: { services?: Array<{ id: string }> } | null | undefined,
  services: T[]
) {
  if (!professional) return []
  const assignedServiceIds = new Set((professional.services || []).map((service) => service.id))
  return services.filter((service) => assignedServiceIds.has(service.id))
}

export function appendPreferredEmoji(
  currentValue: string,
  emoji: string,
  maxItems = 6,
  maxLength = 80
) {
  const normalizedEmoji = typeof emoji === 'string' ? emoji.trim() : ''
  const items = currentValue
    .split(',')
    .map((item) => item.trim())
    .filter(Boolean)
  if (!normalizedEmoji) return { value: items.join(', '), added: false, reason: 'invalid' as const }
  if (items.includes(normalizedEmoji)) {
    return { value: items.join(', '), added: false, reason: 'duplicate' as const }
  }
  if (items.length >= maxItems) {
    return { value: items.join(', '), added: false, reason: 'limit' as const }
  }
  const value = [...items, normalizedEmoji].join(', ')
  if (value.length > maxLength) {
    return { value: items.join(', '), added: false, reason: 'length' as const }
  }
  return { value, added: true, reason: null }
}

