    async function setProfessionalStatus(id, isActive) {
      const professional = state.professionals.find((item) => item.id === id)
      if (!professional) return

      if (!isActive) {
        const impact = await getProfessionalImpact(id)
        if (impact.futureAppointments.length > 0) {
          showProfessionalImpact({
            title: 'Turnos futuros de ' + professional.name,
            copy: 'Si lo desactivas, no se ofreceran nuevos turnos, pero estos turnos siguen vigentes hasta que los reprogrames o canceles.',
            appointments: impact.futureAppointments,
            professionalId: id
          })
        }
      }

      try {
        await getJson('/professionals/' + id + '/status', {
          method: 'PATCH',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ isActive })
        })
        els.professionalFeedback.textContent = isActive ? 'Profesional activado.' : 'Profesional desactivado para nuevas reservas.'
        state.professionals = await getJson(businessScopedPath('/professionals'))
        state.professionalMediaBusinessId = state.businessId
        renderProfessionals()
        renderStaffUsers()
        renderAgendaFilters()
        renderAppointmentFormOptions()
        renderAgenda()
      } catch (error) {
        els.professionalFeedback.textContent = error.message
      }
    }

    async function getProfessionalImpact(id) {
      return getJson('/professionals/' + id + '/appointments-impact')
    }

    function showProfessionalImpact(input) {
      state.pendingImpactAppointments = input.appointments || []
      els.professionalImpactTitle.textContent = input.title
      els.professionalImpactCopy.textContent = input.copy
      els.professionalImpactList.innerHTML = input.appointments.length
        ? input.appointments.map((appointment) => {
            const customer = appointment.customer?.name || 'Cliente'
            const phone = appointment.customer?.phone || 'Sin telefono'
            const service = appointmentServiceLabel(appointment)
            return '<button class="item" type="button" data-impact-appointment="' + appointment.id + '">' +
              '<div class="item-title">' + escapeHtml(customer + ' - ' + service) + '</div>' +
              '<p>' + escapeHtml(formatAppointment(appointment.startAt) + ' · ' + phone) + '</p>' +
            '</button>'
          }).join('')
        : '<div class="empty">No hay turnos futuros afectados.</div>'

      for (const button of els.professionalImpactList.querySelectorAll('[data-impact-appointment]')) {
        button.addEventListener('click', () => {
          openImpactedAppointmentInAgenda(button.dataset.impactAppointment).catch((error) => showCrmToast(error.message, 'error'))
        })
      }

      els.professionalImpactPanel.classList.add('visible')
      els.professionalImpactPanel.scrollIntoView({ behavior: 'smooth', block: 'start' })
    }

    function hideProfessionalImpact() {
      els.professionalImpactPanel.classList.remove('visible')
      els.professionalImpactList.innerHTML = ''
      state.pendingImpactContext = null
      state.pendingImpactAppointments = []
    }

    async function refreshScheduleBlockImpactPanel() {
      if (!state.businessId || state.pendingProfessionalSave) return
      const from = startOfDay(new Date())
      const to = addDays(from, 60)
      const params = new URLSearchParams({
        businessId: state.businessId,
        from: from.toISOString(),
        to: to.toISOString()
      })

      const [blocks, appointments] = await Promise.all([
        getJson('/schedule-blocks?' + params.toString()),
        getJson('/appointments?' + params.toString())
      ])

      const affectedAppointments = appointments
        .filter((appointment) => appointment.status !== 'CANCELLED' && appointment.status !== 'NO_SHOW')
        .filter((appointment) => blocks.some((block) => scheduleBlockAffectsAppointment(block, appointment)))

      if (!affectedAppointments.length) {
        if (state.pendingImpactContext === 'schedule-block') hideProfessionalImpact()
        return
      }

      state.pendingImpactContext = 'schedule-block'
      showProfessionalImpact({
        title: 'Turnos afectados por bloqueos',
        copy: 'Estos turnos caen dentro de feriados, vacaciones o ausencias cargadas. Reprogramalos desde Agenda o contacta al cliente antes de moverlos.',
        appointments: uniqueAppointmentsById(affectedAppointments)
      })
    }

    function scheduleBlockAffectsAppointment(block, appointment) {
      if (block.professionalId && block.professionalId !== appointment.professionalId) return false
      const blockStart = new Date(block.startAt)
      const blockEnd = new Date(block.endAt)
      const appointmentStart = new Date(appointment.startAt)
      const duration = appointment.totalDurationMinutes || appointment.service?.duration || Number(els.agendaStep?.value || 15)
      const appointmentEnd = addMinutes(appointmentStart, duration)
      return appointmentStart < blockEnd && appointmentEnd > blockStart
    }

    function uniqueAppointmentsById(appointments) {
      const seen = new Set()
      return appointments.filter((appointment) => {
        if (seen.has(appointment.id)) return false
        seen.add(appointment.id)
        return true
      })
    }

    async function openImpactedAppointmentInAgenda(appointmentId = '') {
      const impactedAppointment = state.pendingImpactAppointments.find((appointment) => appointment.id === appointmentId) ||
        state.pendingImpactAppointments[0]
      if (!impactedAppointment) {
        setSection('agenda')
        return
      }

      const appointmentStart = new Date(impactedAppointment.startAt)
      state.agendaSelectedDate = appointmentStart
      state.agendaMonthDate = new Date(appointmentStart)
      if (els.agendaProfessional && impactedAppointment.professionalId) {
        els.agendaProfessional.value = impactedAppointment.professionalId
        if (els.agendaProfessional.value !== impactedAppointment.professionalId) els.agendaProfessional.value = ''
      }
      if (els.agendaService && impactedAppointment.serviceId) {
        els.agendaService.value = impactedAppointment.serviceId
        if (els.agendaService.value !== impactedAppointment.serviceId) els.agendaService.value = ''
      }
      setSection('agenda')
      await loadAgenda()
      const appointment = state.agendaAppointments.find((item) => item.id === impactedAppointment.id) || impactedAppointment
      openAppointmentDialog({ appointment })
      showCrmToast('Turno afectado abierto para reprogramar.', 'success')
    }

    function buildProfessionalWorkingHours() {
      return readWeeklySchedule(professionalDayInputs())
    }

    function weeklyScheduleInputs(prefix, defaults) {
      return [
        { key: 'monday', dayOfWeek: 1, label: 'lunes', weekend: false },
        { key: 'tuesday', dayOfWeek: 2, label: 'martes', weekend: false },
        { key: 'wednesday', dayOfWeek: 3, label: 'miercoles', weekend: false },
        { key: 'thursday', dayOfWeek: 4, label: 'jueves', weekend: false },
        { key: 'friday', dayOfWeek: 5, label: 'viernes', weekend: false },
        { key: 'saturday', dayOfWeek: 6, label: 'sabado', weekend: true },
        { key: 'sunday', dayOfWeek: 0, label: 'domingo', weekend: true }
      ].map((day) => {
        const enabled = document.getElementById(prefix + '-' + day.key + '-enabled')
        const row = enabled.closest('[data-weekly-schedule-day]')
        return {
          ...day,
          prefix,
          row,
          enabled,
          ranges: row.querySelector('.weekly-schedule-ranges'),
          add: row.querySelector('[data-weekly-schedule-add]'),
          start: row.querySelector('input[type="time"]'),
          defaultStart: defaults.start,
          defaultEnd: day.weekend ? defaults.weekendEnd : defaults.weekdayEnd
        }
      })
    }

    function professionalDayInputs() {
      return weeklyScheduleInputs('professional', {
        start: '09:00',
        weekdayEnd: '18:00',
        weekendEnd: '14:00'
      })
    }

    function businessDayInputs() {
      return weeklyScheduleInputs('business', {
        start: '09:00',
        weekdayEnd: '19:00',
        weekendEnd: '14:00'
      })
    }

    function readWeeklySchedule(days) {
      return days.flatMap((day) => {
        if (!day.enabled.checked) return []
        return Array.from(day.ranges.querySelectorAll('.weekly-schedule-range')).map((range) => {
          const inputs = range.querySelectorAll('input[type="time"]')
          return {
            dayOfWeek: day.dayOfWeek,
            startTime: inputs[0]?.value || '',
            endTime: inputs[1]?.value || ''
          }
        })
      })
    }

    function invalidWeeklyScheduleDay(days) {
      return days.find((day) => {
        if (!day.enabled.checked) return false
        const ranges = readWeeklySchedule([day]).sort((left, right) => left.startTime.localeCompare(right.startTime))
        if (!ranges.length) return true
        if (ranges.some((range) => !range.startTime || !range.endTime || range.startTime >= range.endTime)) return true
        return ranges.some((range, index) => index > 0 && range.startTime < ranges[index - 1].endTime)
      })
    }

    function syncWeeklyScheduleDay(day) {
      const disabled = day.enabled.disabled || !day.enabled.checked
      day.row.classList.toggle('is-closed', disabled)
      day.ranges.querySelectorAll('input, button').forEach((input) => {
        input.disabled = disabled
      })
      day.add.disabled = disabled
    }

    function setWeeklySchedule(days, hours) {
      for (const day of days) {
        const dayHours = (hours || [])
          .filter((hour) => hour.dayOfWeek === day.dayOfWeek)
          .sort((left, right) => left.startTime.localeCompare(right.startTime))
        day.enabled.checked = dayHours.length > 0 && !day.enabled.disabled
        replaceWeeklyScheduleRanges(day, dayHours.length ? dayHours : [{
          startTime: day.defaultStart,
          endTime: day.defaultEnd
        }])
        syncWeeklyScheduleDay(day)
      }
    }

    function replaceWeeklyScheduleRanges(day, hours) {
      day.ranges.innerHTML = ''
      hours.forEach((hour, index) => {
        day.ranges.appendChild(createWeeklyScheduleRange(day, hour.startTime, hour.endTime, index === 0))
      })
    }

    function createWeeklyScheduleRange(day, startTime, endTime, firstRange = false) {
      const range = document.createElement('div')
      range.className = 'weekly-schedule-range'

      const start = document.createElement('input')
      start.className = 'field'
      start.type = 'time'
      start.value = startTime
      start.setAttribute('aria-label', 'Hora de inicio')
      if (firstRange) start.id = day.prefix + '-' + day.key + '-start'

      const separator = document.createElement('span')
      separator.className = 'schedule-separator'
      separator.textContent = 'a'

      const end = document.createElement('input')
      end.className = 'field'
      end.type = 'time'
      end.value = endTime
      end.setAttribute('aria-label', 'Hora de cierre')
      if (firstRange) end.id = day.prefix + '-' + day.key + '-end'

      const remove = document.createElement('button')
      remove.className = 'weekly-schedule-remove'
      remove.type = 'button'
      remove.setAttribute('aria-label', 'Eliminar horario')
      remove.innerHTML = '&times;'

      range.append(start, separator, end, remove)
      return range
    }

    function addWeeklyScheduleRange(day) {
      const previous = day.ranges.querySelector('.weekly-schedule-range:last-child')
      const previousInputs = previous?.querySelectorAll('input[type="time"]')
      const suggestedStart = previousInputs?.[1]?.value || '16:00'
      const suggestedEnd = suggestedStart < '21:00' ? '21:00' : day.defaultEnd
      day.ranges.appendChild(createWeeklyScheduleRange(day, suggestedStart, suggestedEnd, !previous))
      syncWeeklyScheduleDay(day)
    }

    function removeWeeklyScheduleRange(day, button) {
      button.closest('.weekly-schedule-range')?.remove()
      const firstRange = day.ranges.querySelector('.weekly-schedule-range')
      if (!firstRange) {
        day.enabled.checked = false
      } else {
        const inputs = firstRange.querySelectorAll('input[type="time"]')
        if (inputs[0]) inputs[0].id = day.prefix + '-' + day.key + '-start'
        if (inputs[1]) inputs[1].id = day.prefix + '-' + day.key + '-end'
      }
      syncWeeklyScheduleDay(day)
    }

    function copyMondayScheduleToWeekdays(prefix) {
      const days = prefix === 'business' ? businessDayInputs() : professionalDayInputs()
      const monday = days.find((day) => day.dayOfWeek === 1)
      if (!monday) return
      const mondayHours = readWeeklySchedule([monday])
      for (const day of days.filter((item) => item.dayOfWeek >= 2 && item.dayOfWeek <= 5)) {
        day.enabled.checked = mondayHours.length > 0 && !day.enabled.disabled
        replaceWeeklyScheduleRanges(day, mondayHours.length
          ? mondayHours.map((hour) => ({ startTime: hour.startTime, endTime: hour.endTime }))
          : [{ startTime: day.defaultStart, endTime: day.defaultEnd }])
        syncWeeklyScheduleDay(day)
      }
    }

    function businessHoursForDay(dayOfWeek) {
      return state.businessHours.filter((hour) => hour.dayOfWeek === dayOfWeek)
    }

    function isInsideConfiguredBusinessHours(hour) {
      return businessHoursForDay(hour.dayOfWeek).some((businessHour) => {
        return hour.startTime >= businessHour.startTime &&
          hour.endTime <= businessHour.endTime
      })
    }

    function validateProfessionalHoursAgainstBusiness(hours) {
      const invalidHour = hours.find((hour) => !isInsideConfiguredBusinessHours(hour))
      if (!invalidHour) return ''

      const ranges = businessHoursForDay(invalidHour.dayOfWeek)
      const localRange = ranges.length
        ? ranges.map((hour) => hour.startTime + ' a ' + hour.endTime).join(', ')
        : 'cerrado'

      return 'El horario de ' + dayName(invalidHour.dayOfWeek) + ' debe estar dentro del horario del local (' + localRange + ').'
    }

    function applyProfessionalBusinessHourLimits() {
      for (const day of professionalDayInputs()) {
        const localHours = businessHoursForDay(day.dayOfWeek)
        day.enabled.disabled = localHours.length === 0
        if (day.enabled.disabled) {
          day.enabled.checked = false
        }
        day.ranges.querySelectorAll('input[type="time"]').forEach((input) => {
          input.min = ''
          input.max = ''
        })
        syncWeeklyScheduleDay(day)
      }
    }

