    async function loadFacebookSdk(apiVersion) {
      if (window.FB) return window.FB
      return new Promise((resolve, reject) => {
        window.fbAsyncInit = function () {
          resolve(window.FB)
        }
        const existing = document.getElementById('facebook-jssdk')
        if (existing) {
          const startedAt = Date.now()
          const waitForSdk = window.setInterval(() => {
            if (window.FB) {
              window.clearInterval(waitForSdk)
              resolve(window.FB)
            } else if (Date.now() - startedAt > 8000) {
              window.clearInterval(waitForSdk)
              reject(new Error('Meta tardo demasiado en cargar el SDK. Volve a intentar.'))
            }
          }, 150)
          return
        }
        const script = document.createElement('script')
        script.id = 'facebook-jssdk'
        script.async = true
        script.defer = true
        script.crossOrigin = 'anonymous'
        script.src = 'https://connect.facebook.net/es_LA/sdk.js'
        script.onerror = () => reject(new Error('No pude cargar el SDK de Meta. Revisa la conexion e intenta de nuevo.'))
        document.body.appendChild(script)
      }).then((FB) => {
        if (!FB) throw new Error('Meta no devolvio el SDK de Facebook.')
        return FB
      })
    }

    function listenForWhatsappEmbeddedSignup() {
      if (state.whatsappEmbeddedSignupListenerReady) return
      window.addEventListener('message', (event) => {
        if (event.origin === window.location.origin && event.data?.type === 'SALON_AI_META_OAUTH') {
          if (event.data.error) {
            showWhatsappSettingsFeedback(event.data.error, 'error')
            return
          }
          void handleWhatsappSignupResponse({ authResponse: { code: event.data.code } }, event.data.redirectUri)
          return
        }
        if (!isFacebookMessageOrigin(event.origin)) return
        let data = event.data
        if (typeof data === 'string') {
          try {
            data = JSON.parse(data)
          } catch {
            recordWhatsappMetaMessage(event.origin, ['non_json_string', 'sample:' + data.slice(0, 48)])
            return
          }
        }
        recordWhatsappMetaMessage(event.origin, collectObjectKeys(data))
        if (!data || data.type !== 'WA_EMBEDDED_SIGNUP') return
        if (data.event && data.event !== 'FINISH') {
          state.whatsappEmbeddedSignupPayloadKeys = collectObjectKeys(data.data || data)
          return
        }
        const payload = data.data || data
        const payloadKeys = collectObjectKeys(payload)
        const phoneNumber = findFirstNestedValue(payload, [
          'phone_number_id',
          'phoneNumberId',
          'phone_number.id',
          'phoneNumber.id',
          'phone.id',
          'phoneNumberID',
          'phone_number.id'
        ])
        const displayPhone = findFirstNestedValue(payload, [
          'display_phone_number',
          'displayPhoneNumber',
          'phone_number.display_phone_number',
          'phoneNumber.displayPhoneNumber',
          'phone.display_phone_number'
        ])
        const wabaId = findFirstNestedValue(payload, [
          'waba_id',
          'wabaId',
          'whatsapp_business_account_id',
          'whatsappBusinessAccountId',
          'whatsapp_business_account.id',
          'whatsappBusinessAccount.id',
          'waba.id'
        ])
        state.whatsappEmbeddedSignupSession = {
          wabaId: wabaId || state.whatsappEmbeddedSignupSession?.wabaId,
          phoneNumberId: phoneNumber || state.whatsappEmbeddedSignupSession?.phoneNumberId,
          displayPhoneNumber: displayPhone || state.whatsappEmbeddedSignupSession?.displayPhoneNumber
        }
        state.whatsappEmbeddedSignupPayloadKeys = payloadKeys
        if (state.whatsappPendingSignupResponse && !state.whatsappSignupSaveInFlight && state.whatsappEmbeddedSignupSession.wabaId && state.whatsappEmbeddedSignupSession.phoneNumberId) {
          const pending = state.whatsappPendingSignupResponse
          state.whatsappPendingSignupResponse = null
          void handleWhatsappSignupResponse(pending.response, pending.redirectUri)
        }
      })
      state.whatsappEmbeddedSignupListenerReady = true
    }

    function isFacebookMessageOrigin(origin) {
      try {
        const hostname = new URL(origin).hostname
        return hostname === 'facebook.com' || hostname.endsWith('.facebook.com')
      } catch {
        return false
      }
    }

    function recordWhatsappMetaMessage(origin, keys) {
      const summary = String(origin || 'unknown') + ' [' + (keys || []).slice(0, 8).join(', ') + ']'
      if (state.whatsappMetaMessagesSeen.includes(summary)) return
      state.whatsappMetaMessagesSeen = [...state.whatsappMetaMessagesSeen, summary].slice(-8)
    }

    function collectObjectKeys(value, prefix = '', result = []) {
      if (!value || typeof value !== 'object') return result
      for (const key of Object.keys(value)) {
        const path = prefix ? prefix + '.' + key : key
        result.push(path)
        if (value[key] && typeof value[key] === 'object' && result.length < 40) {
          collectObjectKeys(value[key], path, result)
        }
      }
      return result.slice(0, 40)
    }

    function findFirstNestedValue(source, paths) {
      for (const path of paths) {
        const value = path.split('.').reduce((current, key) => current && current[key], source)
        if (typeof value === 'string' && value.trim()) return value.trim()
      }
      return ''
    }

    async function handleWhatsappSignupResponse(response, redirectUri) {
      try {
        state.whatsappSignupSaveInFlight = true
        const code = response?.authResponse?.code
        const accessToken = response?.authResponse?.accessToken
        const expiresIn = Number(response?.authResponse?.expiresIn)
        if (!code && !accessToken) {
          showWhatsappSettingsFeedback('Meta no devolvio autorizacion. Volve a intentar la conexion.', 'error')
          return
        }
        await waitForWhatsappEmbeddedSignupSession()
        const hasEmbeddedSignupAssets = Boolean(state.whatsappEmbeddedSignupSession?.wabaId && state.whatsappEmbeddedSignupSession?.phoneNumberId)
        if (!hasEmbeddedSignupAssets && !state.whatsappPendingSignupResponse) {
          state.whatsappPendingSignupResponse = { response, redirectUri }
        }
        state.whatsappSettings = await getJson('/businesses/' + state.businessId + '/whatsapp/embedded-signup-callback', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            code,
            accessToken,
            tokenExpiresAt: Number.isFinite(expiresIn) ? new Date(Date.now() + expiresIn * 1000).toISOString() : undefined,
            redirectUri,
            embeddedSignupReceived: state.whatsappEmbeddedSignupPayloadKeys.length > 0,
            embeddedSignupPayloadKeys: state.whatsappEmbeddedSignupPayloadKeys,
            metaMessagesSeen: state.whatsappMetaMessagesSeen,
            ...state.whatsappEmbeddedSignupSession
          })
        })
        renderWhatsappSettings()
        const lastError = state.whatsappSettings?.connection?.lastError
        const isConnected = state.whatsappSettings?.connection?.status === 'CONNECTED' && state.whatsappSettings?.connection?.wabaId && state.whatsappSettings?.connection?.phoneNumberId
        showWhatsappSettingsFeedback(lastError || (isConnected ? 'WhatsApp conectado para este comercio.' : 'Falta completar WABA ID y Phone Number ID para terminar la conexion.'), lastError || !isConnected ? 'error' : 'success')
      } catch (error) {
        showWhatsappSettingsFeedback(error.message, 'error')
      } finally {
        state.whatsappSignupSaveInFlight = false
      }
    }

    async function waitForWhatsappEmbeddedSignupSession() {
      if (state.whatsappEmbeddedSignupSession?.wabaId && state.whatsappEmbeddedSignupSession?.phoneNumberId) return
      const startedAt = Date.now()
      while (Date.now() - startedAt < 10000) {
        await new Promise((resolve) => window.setTimeout(resolve, 150))
        if (state.whatsappEmbeddedSignupSession?.wabaId && state.whatsappEmbeddedSignupSession?.phoneNumberId) return
      }
    }

    function showWhatsappManualConnectionGuide() {
      els.whatsappManualGuide.hidden = false
      els.whatsappTechnicalForm.scrollIntoView({ behavior: 'smooth', block: 'center' })
      showWhatsappSettingsFeedback('Completa WABA ID, Phone Number ID, numero visible y token desde Meta Business Suite. El guardado termina de habilitar los envios segun las reglas del comercio.', 'success')
      window.setTimeout(() => {
        els.whatsappWabaId.focus()
      }, 250)
    }

    async function openWhatsappSignupPlaceholder() {
      if (!state.businessId) return
      clearWhatsappSettingsFeedback()
      state.whatsappEmbeddedSignupSession = {}
      state.whatsappEmbeddedSignupPayloadKeys = []
      state.whatsappMetaMessagesSeen = []
      state.whatsappPendingSignupResponse = null
      els.whatsappConnectButton.disabled = true
      els.whatsappConnectButton.textContent = 'Abriendo Meta...'
      try {
        const config = await getJson('/businesses/' + state.businessId + '/whatsapp-embedded-signup-config')
        const FB = await loadFacebookSdk(config.apiVersion)
        listenForWhatsappEmbeddedSignup()
        FB.init({
          appId: config.appId,
          autoLogAppEvents: true,
          xfbml: false,
          version: config.apiVersion
        })
        FB.login(function (response) {
          void handleWhatsappSignupResponse(response)
        }, {
          config_id: config.configId,
          response_type: 'token',
          scope: 'whatsapp_business_management,whatsapp_business_messaging',
          extras: config.extras || {}
        })
      } catch (error) {
        showWhatsappSettingsFeedback(error.message, 'error')
      } finally {
        els.whatsappConnectButton.disabled = false
        els.whatsappConnectButton.textContent = 'Conectar WhatsApp'
      }
    }

    function businessInitials(name) {
      const words = String(name || 'S').trim().split(/\s+/).filter(Boolean)
      return words.slice(0, 2).map((word) => word[0]).join('').toUpperCase() || 'S'
    }

    function updateBusinessBrand() {
      const name = state.business?.name || 'Weex'
      const logoUrl = state.business?.logoUrl || null
      const brandName = document.querySelector('.workspace-nav .crm-brand strong')
      const brandMark = document.querySelector('.workspace-nav .brand-mark')
      const adminName = document.querySelector('.workspace-nav .nav-user-info strong')
      const adminRole = document.querySelector('.workspace-nav .nav-user-info span')
      const adminAvatar = document.querySelector('.workspace-nav .mini-avatar')

      if (brandName) brandName.textContent = name
      if (adminName) adminName.textContent = state.currentUser?.name || name
      if (adminRole) adminRole.textContent = state.currentUser?.role === 'SUPER_ADMIN'
        ? 'Super admin'
        : state.currentUser?.role === 'ACCOUNT_ADMIN' ? 'Administrador de cuentas' : 'Administrador'
      if (brandMark) {
        brandMark.innerHTML = logoUrl
          ? '<img src="' + escapeHtml(logoUrl) + '" alt="">'
          : escapeHtml(businessInitials(name))
      }
      if (adminAvatar) {
        adminAvatar.innerHTML = logoUrl
          ? '<img src="' + escapeHtml(logoUrl) + '" alt="">'
          : escapeHtml(businessInitials(state.currentUser?.name || name))
      }
    }

    function setBusinessLogo(logoUrl) {
      state.businessLogoUrl = logoUrl
      els.businessLogoPreview.src = logoUrl || ''
      els.businessLogoPicker.classList.toggle('has-image', Boolean(logoUrl))
      els.businessLogoRemove.hidden = !logoUrl
      if (!logoUrl) {
        els.businessLogo.value = ''
      }
    }

    function readBusinessLogo(event) {
      const file = event.target.files?.[0]
      if (!file) return

      const supportedTypes = ['image/png', 'image/jpeg', 'image/webp', 'image/gif']
      if (!supportedTypes.includes(file.type)) {
        showBusinessSettingsFeedback('Elegí una imagen PNG, JPG, WEBP o GIF.', 'error')
        setBusinessLogo(state.business?.logoUrl || null)
        return
      }

      if (file.size > 2 * 1024 * 1024) {
        showBusinessSettingsFeedback('La imagen no puede superar los 2 MB.', 'error')
        setBusinessLogo(state.business?.logoUrl || null)
        return
      }

      clearBusinessSettingsFeedback()
      optimizeImageFile(file, 512)
        .then(setBusinessLogo)
        .catch(() => showBusinessSettingsFeedback('No pude optimizar el logo seleccionado.', 'error'))
    }

    function setLandingCover(coverUrl) {
      state.landingCoverUrl = coverUrl
      els.landingCoverImage.src = coverUrl || ''
      els.landingCoverPreview.classList.toggle('has-image', Boolean(coverUrl))
      els.landingCoverRemove.hidden = !coverUrl
      if (!coverUrl) {
        els.landingCover.value = ''
      }
    }

    function readLandingCover(event) {
      const file = event.target.files?.[0]
      if (!file) return

      const supportedTypes = ['image/png', 'image/jpeg', 'image/webp', 'image/gif']
      if (!supportedTypes.includes(file.type)) {
        showLandingSettingsFeedback('Elegi una portada PNG, JPG, WEBP o GIF.', 'error')
        setLandingCover(state.business?.coverImageUrl || null)
        return
      }

      if (file.size > 3 * 1024 * 1024) {
        showLandingSettingsFeedback('La portada no puede superar los 3 MB.', 'error')
        setLandingCover(state.business?.coverImageUrl || null)
        return
      }

      clearLandingSettingsFeedback()
      optimizeImageFile(file, 1600)
        .then(setLandingCover)
        .catch(() => showLandingSettingsFeedback('No pude optimizar la portada seleccionada.', 'error'))
    }

    function parseLandingGalleryImages(value) {
      if (!value) return []
      if (Array.isArray(value)) return value.filter(Boolean).slice(0, 6)
      try {
        const parsed = JSON.parse(value)
        if (!Array.isArray(parsed)) return []
        return parsed.filter((imageUrl) => typeof imageUrl === 'string' && imageUrl).slice(0, 6)
      } catch {
        return []
      }
    }

    function setLandingGallery(images) {
      state.landingGalleryImages = (images || []).slice(0, 6)
      renderLandingGalleryList()
      if (els.landingGallery) {
        els.landingGallery.value = ''
      }
    }

    function renderLandingGalleryList() {
      if (!els.landingGalleryList) return
      if (!state.landingGalleryImages.length) {
        els.landingGalleryList.innerHTML = '<div class="landing-gallery-empty">Sin im&aacute;genes cargadas</div>'
        return
      }
      els.landingGalleryList.innerHTML = state.landingGalleryImages.map((imageUrl, index) =>
        '<div class="landing-gallery-item">' +
          '<img src="' + escapeHtml(imageUrl) + '" alt="Imagen de galer&iacute;a ' + (index + 1) + '">' +
          '<button class="landing-gallery-remove" type="button" data-remove-gallery-image="' + index + '" aria-label="Quitar imagen">&times;</button>' +
        '</div>'
      ).join('')
    }

    function readLandingGallery(event) {
      const files = Array.from(event.target.files || [])
      if (!files.length) return

      const availableSlots = 6 - state.landingGalleryImages.length
      if (availableSlots <= 0) {
        showLandingSettingsFeedback('La galer&iacute;a permite hasta 6 im&aacute;genes.', 'error')
        event.target.value = ''
        return
      }
      if (files.length > availableSlots) {
        showLandingSettingsFeedback('Pod&eacute;s agregar hasta ' + availableSlots + ' imagen' + (availableSlots === 1 ? '' : 'es') + ' m&aacute;s.', 'error')
        event.target.value = ''
        return
      }

      const supportedTypes = ['image/png', 'image/jpeg', 'image/webp', 'image/gif']
      if (files.some((file) => !supportedTypes.includes(file.type))) {
        showLandingSettingsFeedback('La galer&iacute;a acepta PNG, JPG, WEBP o GIF.', 'error')
        event.target.value = ''
        return
      }
      if (files.some((file) => file.size > 3 * 1024 * 1024)) {
        showLandingSettingsFeedback('Cada imagen de la galer&iacute;a no puede superar los 3 MB.', 'error')
        event.target.value = ''
        return
      }

      Promise.all(files.map((file) => optimizeImageFile(file, 1200)))
        .then((images) => {
          clearLandingSettingsFeedback()
          setLandingGallery([...state.landingGalleryImages, ...images])
        })
        .catch(() => {
          showLandingSettingsFeedback('No pude leer una de las im&aacute;genes de la galer&iacute;a.', 'error')
          event.target.value = ''
        })
    }

    function readFileAsDataUrl(file) {
      return new Promise((resolve, reject) => {
        const reader = new FileReader()
        reader.addEventListener('load', () => resolve(String(reader.result || '')))
        reader.addEventListener('error', reject)
        reader.readAsDataURL(file)
      })
    }

    async function optimizeImageFile(file, maxDimension) {
      if (file.type === 'image/gif') return readFileAsDataUrl(file)
      const bitmap = await createImageBitmap(file)
      try {
        const scale = Math.min(1, maxDimension / Math.max(bitmap.width, bitmap.height))
        const width = Math.max(1, Math.round(bitmap.width * scale))
        const height = Math.max(1, Math.round(bitmap.height * scale))
        const canvas = document.createElement('canvas')
        canvas.width = width
        canvas.height = height
        const context = canvas.getContext('2d')
        if (!context) throw new Error('No pude preparar la imagen')
        context.drawImage(bitmap, 0, 0, width, height)
        const blob = await new Promise((resolve, reject) => {
          canvas.toBlob((result) => result ? resolve(result) : reject(new Error('No pude convertir la imagen')), 'image/webp', 0.82)
        })
        return readFileAsDataUrl(blob)
      } finally {
        bitmap.close()
      }
    }

    function showBusinessSettingsFeedback(message, type) {
      els.businessSettingsFeedback.textContent = message
      els.businessSettingsFeedback.className = 'settings-feedback visible ' + type
    }

    function clearBusinessSettingsFeedback() {
      els.businessSettingsFeedback.textContent = ''
      els.businessSettingsFeedback.className = 'settings-feedback'
    }

    function showLandingSettingsFeedback(message, type) {
      els.landingSettingsFeedback.textContent = message
      els.landingSettingsFeedback.className = 'settings-feedback visible ' + type
    }

    function clearLandingSettingsFeedback() {
      els.landingSettingsFeedback.textContent = ''
      els.landingSettingsFeedback.className = 'settings-feedback'
    }

    function showAutomationSettingsFeedback(message, type) {
      els.automationSettingsFeedback.textContent = message
      els.automationSettingsFeedback.className = 'settings-feedback visible ' + type
    }

    function clearAutomationSettingsFeedback() {
      els.automationSettingsFeedback.textContent = ''
      els.automationSettingsFeedback.className = 'settings-feedback'
    }

    function showCampaignTemplateFeedback(message, type) {
      els.campaignTemplateFeedback.textContent = message
      els.campaignTemplateFeedback.className = 'campaign-form-feedback ' + (type || '')
    }

    const campaignTemplateStatusLabels = {
      NOT_CREATED: 'Sin crear',
      PENDING: 'Pendiente',
      IN_APPEAL: 'En revision',
      APPROVED: 'Aprobada',
      REJECTED: 'Rechazada',
      PAUSED: 'Pausada',
      DISABLED: 'Deshabilitada'
    }

    function campaignTemplateStatusClass(status) {
      if (status === 'APPROVED') return 'approved'
      if (status === 'REJECTED' || status === 'DISABLED') return 'rejected'
      if (status === 'PENDING' || status === 'IN_APPEAL') return 'pending'
      return 'neutral'
    }

    function renderCampaignTemplateState() {
      const meta = state.campaignTemplateMeta
      const status = meta.status || 'NOT_CREATED'
      const label = campaignTemplateStatusLabels[status] || status
      const reason = meta.rejectionReason
        ? '<small>Motivo: ' + escapeHtml(meta.rejectionReason) + '</small>'
        : meta.lastSyncedAt
          ? '<small>Actualizado ' + escapeHtml(formatDateTime(meta.lastSyncedAt)) + '</small>'
          : ''
      els.campaignTemplateState.innerHTML = '<span class="campaign-template-status ' + campaignTemplateStatusClass(status) + '">' + escapeHtml(label) + '</span>' + reason
      els.campaignTemplateSync.hidden = !els.campaignId.value || !els.campaignTemplateName.value.trim()
    }

    async function syncCampaignTemplateInMeta() {
      const campaignId = els.campaignId.value
      if (!campaignId) return
      els.campaignTemplateSync.disabled = true
      showCampaignTemplateFeedback('Consultando estado en Meta...', '')
      try {
        const campaign = await getJson('/campaigns/' + campaignId + '/template/sync', { method: 'POST' })
        state.campaignTemplateMeta = {
          name: campaign.templateName || null,
          id: campaign.templateId || null,
          status: campaign.templateStatus || 'NOT_CREATED',
          rejectionReason: campaign.templateRejectionReason || null,
          lastSyncedAt: campaign.templateLastSyncedAt || null
        }
        const index = state.campaigns.findIndex((item) => item.id === campaign.id)
        if (index >= 0) state.campaigns[index] = campaign
        renderCampaignTemplateState()
        showCampaignTemplateFeedback('Estado actualizado desde Meta.', 'success')
      } catch (error) {
        showCampaignTemplateFeedback(error.message, 'error')
      } finally {
        els.campaignTemplateSync.disabled = false
      }
    }

    async function createCampaignTemplateInMeta() {
      const name = els.campaignTemplateName.value.trim()
      const bodyText = els.campaignMessage.value.trim()
      if (!name || !/^[a-z0-9_]{1,512}$/.test(name)) {
        showCampaignTemplateFeedback('Indica un nombre valido: minusculas, numeros y guiones bajos.', 'error')
        return
      }
      if (!bodyText) {
        showCampaignTemplateFeedback('Escribi primero el mensaje de la campana.', 'error')
        return
      }
      if (bodyText.length > 1024) {
        showCampaignTemplateFeedback('Meta permite hasta 1024 caracteres en el cuerpo de esta plantilla.', 'error')
        return
      }

      els.campaignTemplateCreate.disabled = true
      els.campaignTemplateCreate.textContent = 'Enviando a Meta...'
      showCampaignTemplateFeedback('Enviando plantilla a revision de Meta...', '')
      try {
        const result = await getJson('/whatsapp/message-templates', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            name,
            languageCode: els.campaignTemplateLanguage.value,
            category: 'MARKETING',
            bodyText
          })
        })
        showCampaignTemplateFeedback(
          'Plantilla enviada a Meta. Estado: ' + (result.status || 'PENDING') + '. Cuando figure aprobada, la campana podra usarla.',
          'success'
        )
        state.campaignTemplateMeta = {
          name,
          id: result.id || null,
          status: result.status || 'PENDING',
          rejectionReason: null,
          lastSyncedAt: new Date().toISOString()
        }
        renderCampaignTemplateState()
      } catch (error) {
        showCampaignTemplateFeedback(error.message, 'error')
      } finally {
        els.campaignTemplateCreate.disabled = false
        els.campaignTemplateCreate.textContent = 'Enviar plantilla a revision'
      }
    }

    function businessHoursKey(hours) {
      return hours
        .map((hour) => hour.dayOfWeek + ':' + hour.startTime + '-' + hour.endTime)
        .sort()
        .join('|')
    }

    async function saveLandingSettings(event) {
      event.preventDefault()
      clearLandingSettingsFeedback()
      if (!state.businessId) return

      const slug = normalizeLandingSlug(els.landingSlug.value)
      if (!slug) {
        showLandingSettingsFeedback('Completa el subdominio de la landing.', 'error')
        return
      }
      const selectedTemplate = document.querySelector('input[name="landing-template"]:checked')?.value || 'classic'
      const styleContent = landingStyleContentFromForm()
      const salonWhiteContent = salonWhiteContentFromForm()
      const luxeNailsContent = luxeNailsContentFromForm()
      if (['classic', 'editorial'].includes(selectedTemplate) && Object.entries(styleContent).some(([key, value]) => key !== 'brandIcon' && !value)) {
        const templateName = LANDING_TEMPLATE_DEFINITIONS[selectedTemplate]?.name || 'seleccionada'
        showLandingSettingsFeedback('Completá todos los textos de la plantilla ' + templateName + '.', 'error')
        return
      }
      if (selectedTemplate === 'salon-white' && Object.values(salonWhiteContent).some((value) => !value)) {
        showLandingSettingsFeedback('Completá los cuatro textos de la plantilla Studio claro.', 'error')
        return
      }
      if (selectedTemplate === 'luxe-nails' && Object.values(luxeNailsContent).some((value) => !value)) {
        showLandingSettingsFeedback('Completá todos los textos e indicadores de la plantilla Luxe Nails.', 'error')
        return
      }
      els.landingSlug.value = slug
      if (!setButtonLoading(els.landingSettingsSubmit, true, 'Guardando...')) return

      try {
        state.business = await getJson('/businesses/' + state.businessId, {
          method: 'PATCH',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            landingEnabled: els.landingEnabled.checked,
            landingTemplate: selectedTemplate,
            slug,
            landingSubtitle: els.landingSubtitle.value.trim() || null,
            landingFeature: els.landingFeature.value.trim() || null,
            landingDescription: els.landingDescription.value.trim() || null,
            landingTemplateContent: {
              ...(state.business?.landingTemplateContent || {}),
              classic: selectedTemplate === 'classic' ? styleContent : classicContentWithLegacyDefaults(),
              ...(['classic', 'editorial'].includes(selectedTemplate) ? { [selectedTemplate]: styleContent } : {}),
              ...(selectedTemplate === 'salon-white' ? { 'salon-white': salonWhiteContent } : {}),
              ...(selectedTemplate === 'luxe-nails' ? { 'luxe-nails': luxeNailsContent } : {})
            },
            coverImageUrl: state.landingCoverUrl,
            landingGalleryImages: state.landingGalleryImages
          })
        })
        state.businessMediaBusinessId = state.businessId
        renderLandingSettings()
        showLandingSettingsFeedback('Landing guardada correctamente.', 'success')
      } catch (error) {
        showLandingSettingsFeedback(error.message, 'error')
      } finally {
        setButtonLoading(els.landingSettingsSubmit, false)
      }
    }

    async function saveBusinessSettings(event) {
      event.preventDefault()
      clearBusinessSettingsFeedback()
      const name = els.businessName.value.trim()
      if (!state.businessId || !name) {
        showBusinessSettingsFeedback('Completa el nombre del local.', 'error')
        return
      }

      const businessDays = businessDayInputs()
      const invalidScheduleDay = invalidWeeklyScheduleDay(businessDays)
      if (invalidScheduleDay) {
        showBusinessSettingsFeedback('Revisa el horario de ' + invalidScheduleDay.label + '.', 'error')
        return
      }

      const requestedHours = readWeeklySchedule(businessDays)

      const hoursChanged = businessHoursKey(requestedHours) !== businessHoursKey(state.businessHours)
      const nameChanged = name !== state.business?.name
      const logoChanged = state.businessLogoUrl !== (state.business?.logoUrl || null)
      const contactEmail = els.businessEmail.value.trim()
      const instagramUrl = els.businessInstagram.value.trim()
      const facebookUrl = els.businessFacebook.value.trim()
      const tiktokUrl = els.businessTiktok.value.trim()
      const publicAddress = els.landingAddress.value.trim()
      const publicAddressArea = els.landingAddressArea.value.trim()
      const publicMapsUrl = els.landingMapsUrl.value.trim()
      const openingYear = els.landingOpeningYear.value ? Number(els.landingOpeningYear.value) : null
      const currentYear = new Date().getFullYear()
      if (openingYear !== null && (!Number.isInteger(openingYear) || openingYear < 1900 || openingYear > currentYear)) {
        showBusinessSettingsFeedback('El año de apertura debe estar entre 1900 y ' + currentYear + '.', 'error')
        return
      }
      if (publicAddress && !publicMapsUrl) {
        showBusinessSettingsFeedback('Pegá el link de Google Maps para que la dirección abra el mapa.', 'error')
        return
      }
      if (publicMapsUrl && !isGoogleMapsUrl(publicMapsUrl)) {
        showBusinessSettingsFeedback('Pegá un link válido de Google Maps.', 'error')
        return
      }
      const contactEmailChanged = contactEmail !== (state.business?.contactEmail || '')
      const instagramChanged = instagramUrl !== (state.business?.instagramUrl || '')
      const facebookChanged = facebookUrl !== (state.business?.facebookUrl || '')
      const tiktokChanged = tiktokUrl !== (state.business?.tiktokUrl || '')
      const publicAddressChanged = publicAddress !== (state.business?.publicAddress || '')
      const publicAddressAreaChanged = publicAddressArea !== (state.business?.publicAddressArea || '')
      const publicMapsUrlChanged = publicMapsUrl !== (state.business?.publicMapsUrl || '')
      const openingYearChanged = openingYear !== (state.business?.landingOpeningYear || null)
      if (!setButtonLoading(els.businessSettingsSubmit, true, 'Guardando...')) return

      try {
        if (hoursChanged) {
          state.businessHours = await getJson('/business-hours/setup', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              businessId: state.businessId,
              schedules: requestedHours.map((hour) => ({
                days: [hour.dayOfWeek],
                startTime: hour.startTime,
                endTime: hour.endTime
              }))
            })
          })
        }
        if (nameChanged || logoChanged || contactEmailChanged || instagramChanged || facebookChanged || tiktokChanged || publicAddressChanged || publicAddressAreaChanged || publicMapsUrlChanged || openingYearChanged) {
          state.business = await getJson('/businesses/' + state.businessId, {
            method: 'PATCH',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              ...(nameChanged ? { name } : {}),
              ...(logoChanged ? { logoUrl: state.businessLogoUrl } : {}),
              ...(contactEmailChanged ? { contactEmail: contactEmail || null } : {}),
              ...(instagramChanged ? { instagramUrl: instagramUrl || null } : {}),
              ...(facebookChanged ? { facebookUrl: facebookUrl || null } : {}),
              ...(tiktokChanged ? { tiktokUrl: tiktokUrl || null } : {}),
              ...(publicAddressChanged ? { publicAddress: publicAddress || null } : {}),
              ...(publicAddressAreaChanged ? { publicAddressArea: publicAddressArea || null } : {}),
              ...(publicMapsUrlChanged ? { publicMapsUrl: publicMapsUrl || null } : {}),
              ...(openingYearChanged ? { landingOpeningYear: openingYear } : {})
            })
          })
          state.businessMediaBusinessId = state.businessId
        }
        state.paymentSettings = await getJson('/businesses/' + state.businessId + '/payment-settings', {
          method: 'PATCH',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            transferEnabled: els.paymentTransferEnabled.checked,
            alias: els.paymentAlias.value.trim() || null,
            cbu: els.paymentCbu.value.trim() || null,
            cvu: els.paymentCvu.value.trim() || null,
            accountHolder: els.paymentAccountHolder.value.trim() || null,
            paymentLinkEnabled: els.paymentLinkEnabled.checked,
            paymentLink: els.paymentLink.value.trim() || null,
            instructions: els.paymentInstructions.value.trim() || null
          })
        })
        renderBusinessSettings()
        applyProfessionalBusinessHourLimits()
        renderAgenda()
        showBusinessSettingsFeedback('Ajustes y medios de pago guardados correctamente.', 'success')
      } catch (error) {
        showBusinessSettingsFeedback(error.message, 'error')
      } finally {
        setButtonLoading(els.businessSettingsSubmit, false)
      }
    }

    function setProfessionalWorkingHours(hours) {
      setWeeklySchedule(professionalDayInputs(), hours)
    }

    function summarizeWorkingHours(hours) {
      if (!hours.length) {
        return 'Sin horarios cargados'
      }

      const grouped = new Map()
      for (const hour of hours) {
        const key = hour.startTime + '-' + hour.endTime
        const days = grouped.get(key) || []
        days.push(hour.dayOfWeek)
        grouped.set(key, days)
      }

      return Array.from(grouped.entries()).map(([timeRange, days]) => {
        return summarizeDays(days) + ' ' + timeRange.replace('-', ' a ')
      }).join(' · ')
    }

    function summarizeDays(days) {
      const sorted = [...days].sort((left, right) => left - right)
      if ([1, 2, 3, 4, 5].every((day) => sorted.includes(day))) {
        const weekend = sorted.filter((day) => day === 0 || day === 6)
        return ['Lun a vie', ...weekend.map(dayName)].join(', ')
      }

      return sorted.map(dayName).join(', ')
    }

    function dayName(dayOfWeek) {
      return ['Dom', 'Lun', 'Mar', 'Mie', 'Jue', 'Vie', 'Sab'][dayOfWeek] || 'Dia'
    }

    function activeProfessionals() {
      return state.professionals.filter((professional) => professional.isActive !== false)
    }

    function agendaProfessionalColor(professionalId, index = 0) {
      const palette = ['#2563eb', '#8b5cf6', '#10b981', '#f97316', '#ef4444', '#14b8a6']
      const professionals = activeProfessionals()
      const resolvedIndex = index >= 0 ? index : professionals.findIndex((professional) => professional.id === professionalId)
      return palette[Math.max(0, resolvedIndex) % palette.length]
    }

    function formatCompactNumber(value) {
      if (value >= 1000) {
        return new Intl.NumberFormat('es-AR', {
          notation: 'compact',
          maximumFractionDigits: 1
        }).format(value)
      }

      return String(value)
    }

    function getProfessionalMetrics() {
      const now = new Date()
      const currentMonth = monthRange(now)
      const previousMonth = monthRange(new Date(now.getFullYear(), now.getMonth() - 1, 1))
      const currentAppointments = appointmentsInRange(currentMonth.start, currentMonth.end)
      const previousAppointments = appointmentsInRange(previousMonth.start, previousMonth.end)
      const currentAttendedAppointments = attendedAppointmentsInRange(currentMonth.start, currentMonth.end)
      const previousAttendedAppointments = attendedAppointmentsInRange(previousMonth.start, previousMonth.end)

      return {
        currentAppointments: currentAppointments.length,
        currentClients: uniqueAppointmentCustomers(currentAttendedAppointments),
        appointmentTrend: percentageChange(currentAppointments.length, previousAppointments.length),
        clientTrend: percentageChange(
          uniqueAppointmentCustomers(currentAttendedAppointments),
          uniqueAppointmentCustomers(previousAttendedAppointments)
        )
      }
    }

    function appointmentsInRange(start, end) {
      return (state.agendaAppointments || [])
        .filter(isActiveAppointment)
        .filter((appointment) => {
          const startAt = new Date(appointment.startAt)
          return startAt >= start && startAt < end
        })
    }

    function attendedAppointmentsInRange(start, end) {
      return (state.agendaAppointments || [])
        .filter(isAttendedAppointment)
        .filter((appointment) => {
          const startAt = new Date(appointment.startAt)
          return startAt >= start && startAt < end
        })
    }

    function uniqueAppointmentCustomers(appointments) {
      return new Set(appointments.map((appointment) => appointment.customerId).filter(Boolean)).size
    }

    function monthRange(date) {
      const start = new Date(date.getFullYear(), date.getMonth(), 1)
      const end = new Date(date.getFullYear(), date.getMonth() + 1, 1)

      return { start, end }
    }

    function percentageChange(current, previous) {
      if (previous === 0) {
        return current === 0 ? 0 : 100
      }

      return Math.round(((current - previous) / previous) * 100)
    }

    function renderMetricTrend(element, value) {
      const sign = value > 0 ? '+' : ''
      element.textContent = sign + value + '%'
      element.classList.toggle('negative', value < 0)
      element.classList.toggle('muted', value === 0)
    }

    function summarizeProfessionalServices(professional) {
      const services = professional.services || []
      if (services.length) {
        return services.map((service) => service.name).join(', ')
      }

      if (!state.services.length) {
        return 'Corte, Color, Peinados'
      }

      return 'Sin servicios asignados'
    }

    function getSelectedProfessionalServiceIds() {
      if (!els.professionalServices) return []

      return Array.from(els.professionalServices.querySelectorAll('input[type="checkbox"]:checked'))
        .map((input) => input.value)
        .filter(Boolean)
    }

    function setSelectedProfessionalServiceIds(serviceIds = []) {
      if (!els.professionalServices) return
      const selected = new Set(serviceIds)

      for (const input of els.professionalServices.querySelectorAll('input[type="checkbox"]')) {
        input.checked = selected.has(input.value)
      }
    }

    function bookableServices() {
      return state.services.filter((service) =>
        service.isBookable !== false &&
        serviceCanContinueToBooking(service)
      )
    }

    function serviceCanContinueToBooking(service) {
      const attentionMode = service.attentionMode || 'DIRECT_BOOKING'
      return attentionMode === 'DIRECT_BOOKING' ||
        attentionMode === 'QUOTE' ||
        service.requiresPhoto === true ||
        (attentionMode === 'GUIDED_ESTIMATE' && service.estimateAllowsBooking !== false)
    }

    function serviceCatalogLabel(service) {
      return service?.parentService
        ? service.parentService.name + ' — ' + service.name
        : service?.name || 'Servicio'
    }

    function renderProfessionalServiceOptions(selectedIds = []) {
      if (!els.professionalServices) return

      const selected = new Set(selectedIds)
      const services = bookableServices()
      els.professionalServices.innerHTML = services.length
        ? services.map((service) => {
            return '<label class="professional-service-option">' +
              '<input type="checkbox" value="' + service.id + '"' + (selected.has(service.id) ? ' checked' : '') + '>' +
              '<span>' + escapeHtml(serviceCatalogLabel(service)) + '</span>' +
            '</label>'
          }).join('')
        : '<div class="professional-form-help">No hay servicios cargados</div>'
    }

    function setProfessionalAvatar(avatarUrl, changed = false) {
      state.professionalAvatarUrl = avatarUrl
      state.professionalAvatarChanged = changed
      els.professionalPhotoPreview.src = avatarUrl || ''
      els.professionalPhotoPicker.classList.toggle('has-image', Boolean(avatarUrl))
      if (!avatarUrl) {
        els.professionalAvatar.value = ''
      }
    }

    function readProfessionalAvatar(event) {
      const file = event.target.files?.[0]
      if (!file) {
        return
      }

      if (!file.type.startsWith('image/')) {
        els.professionalFeedback.textContent = 'Elegí una imagen valida.'
        setProfessionalAvatar(null, true)
        return
      }

      if (file.size > 2 * 1024 * 1024) {
        els.professionalFeedback.textContent = 'La foto no puede superar los 2 MB.'
        event.target.value = ''
        return
      }

      optimizeImageFile(file, 800)
        .then((imageUrl) => setProfessionalAvatar(imageUrl, true))
        .catch(() => {
          els.professionalFeedback.textContent = 'No pude optimizar la foto seleccionada.'
        })
    }

    function summarizeWorkingHourPills(hours) {
      if (!hours.length) {
        return '<span class="professional-hours-pill">Sin horarios</span>'
      }

      return summarizeWorkingHours(hours)
        .split(' \u00b7 ')
        .slice(0, 2)
        .map((value) => '<span class="professional-hours-pill">' + escapeHtml(value.replace(' a ', ' - ')) + '</span>')
        .join('')
    }

    function renderAgendaFilters() {
      const selectedProfessional = els.agendaProfessional.value || ''
      const selectedService = els.agendaService.value || ''
      els.agendaProfessional.innerHTML = ['<option value="">Todos los profesionales</option>']
        .concat(activeProfessionals().map((professional) => {
          return '<option value="' + professional.id + '">' + escapeHtml(professional.name) + '</option>'
        }))
        .join('')
      els.agendaProfessional.value = activeProfessionals().some((professional) => professional.id === selectedProfessional) ? selectedProfessional : ''

      const services = bookableServices()
      els.agendaService.innerHTML = ['<option value="">Todos los servicios</option>']
        .concat(services.map((service) => {
          return '<option value="' + service.id + '">' + escapeHtml(serviceCatalogLabel(service)) + '</option>'
        }))
        .join('')
      els.agendaService.value = services.some((service) => service.id === selectedService) ? selectedService : ''
      renderAgendaProfessionalControls()
    }

    function renderAgendaProfessionalControls() {
      const professionals = activeProfessionals()
      const selected = els.agendaProfessional.value || ''
      const tabs = [
        '<button class="agenda-pro-tab' + (!selected ? ' active' : '') + '" type="button" data-agenda-pro-tab="">' +
          'Todos' +
        '</button>'
      ].concat(professionals.map((professional, index) => {
        const color = agendaProfessionalColor(professional.id, index)
        return '<button class="agenda-pro-tab' + (selected === professional.id ? ' active' : '') + '" type="button" data-agenda-pro-tab="' + professional.id + '">' +
          '<span class="agenda-dot" style="--agenda-color:' + color + '"></span>' +
          escapeHtml(professional.name) +
        '</button>'
      }))

      els.agendaProfessionalTabs.innerHTML = tabs.join('')
      for (const button of els.agendaProfessionalTabs.querySelectorAll('[data-agenda-pro-tab]')) {
        button.addEventListener('click', async () => {
          els.agendaProfessional.value = button.dataset.agendaProTab || ''
          renderAgendaProfessionalControls()
          await loadAgenda()
        })
      }

      els.agendaLegend.innerHTML = '<strong>Profesionales</strong>' + professionals.map((professional, index) => {
        const color = agendaProfessionalColor(professional.id, index)
        return '<div class="agenda-legend-item">' +
          '<span class="agenda-dot" style="--agenda-color:' + color + '"></span>' +
          '<span>' + escapeHtml(professional.name) + '</span>' +
        '</div>'
      }).join('') +
        '<div class="agenda-legend-item"><span class="agenda-dot" style="--agenda-color:#64748b"></span><span>No disponible</span></div>'
    }

    function appointmentServicesForProfessional(professionalId) {
      const professional = state.professionals.find((item) => item.id === professionalId)
      return filterAssignedServices(professional, bookableServices())
    }

    function renderAppointmentServiceOptions(preferredServiceId = '') {
      const services = appointmentServicesForProfessional(els.appointmentProfessional.value)
      els.appointmentService.innerHTML = services.length
        ? services.map((service) => {
            return '<option value="' + service.id + '">' + escapeHtml(serviceCatalogLabel(service)) + ' · ' + service.duration + ' min</option>'
          }).join('')
        : '<option value="">Sin servicios asignados</option>'
      els.appointmentService.disabled = services.length === 0
      els.appointmentService.value = services.some((service) => service.id === preferredServiceId)
        ? preferredServiceId
        : services[0]?.id || ''
      return services
    }

    function renderAppointmentFormOptions() {
      const selectedProfessionalId = els.appointmentProfessional.value
      const selectedServiceId = els.appointmentService.value
      const selectedCustomerId = els.appointmentCustomer.value
      els.appointmentProfessional.innerHTML = activeProfessionals().map((professional) => {
        return '<option value="' + professional.id + '">' + escapeHtml(professional.name) + '</option>'
      }).join('')
      els.appointmentProfessional.value = activeProfessionals().some((professional) => professional.id === selectedProfessionalId)
        ? selectedProfessionalId
        : activeProfessionals()[0]?.id || ''
      renderAppointmentServiceOptions(selectedServiceId)

      const selectedCustomer = state.customers.find((customer) => customer.id === selectedCustomerId)
      els.appointmentCustomerSearch.value = selectedCustomer ? appointmentCustomerLabel(selectedCustomer) : ''
    }

    function appointmentCustomerLabel(customer) {
      const phone = formatCustomerPhone(customer.phone)
      return customer.name + ' - ' + (phone || 'Sin telefono')
    }

    function closeAppointmentCustomerResults() {
      els.appointmentCustomerResults.hidden = true
      els.appointmentCustomerSearch.setAttribute('aria-expanded', 'false')
    }

    function selectAppointmentCustomer(customer) {
      els.appointmentCustomer.value = customer?.id || ''
      els.appointmentCustomerSearch.value = customer ? appointmentCustomerLabel(customer) : ''
      if (customer && !state.customers.some((item) => item.id === customer.id)) state.customers.push(customer)
      syncAppointmentCustomerFields()
      closeAppointmentCustomerResults()
    }

    function renderAppointmentCustomerResults(customers, query) {
      state.appointmentCustomerResultsData = customers
      const createLabel = query ? 'Crear cliente nuevo con estos datos' : 'Crear cliente nuevo'
      els.appointmentCustomerResults.innerHTML =
        '<button type="button" data-create-appointment-customer><strong>+ ' + createLabel + '</strong></button>' +
        (customers.length
          ? customers.map((customer) => {
              return '<button type="button" role="option" data-appointment-customer-id="' + customer.id + '">' +
                '<strong>' + escapeHtml(customer.name) + '</strong><span>' + escapeHtml(formatCustomerPhone(customer.phone)) + '</span>' +
              '</button>'
            }).join('')
          : '<div class="appointment-customer-result-empty">No encontramos clientes con esa b&uacute;squeda.</div>')
      els.appointmentCustomerResults.hidden = false
      els.appointmentCustomerSearch.setAttribute('aria-expanded', 'true')
    }

    async function loadAppointmentCustomerResults(query = '') {
      if (!state.businessId) return
      if (query.length === 1) {
        state.appointmentCustomerResultsData = []
        els.appointmentCustomerResults.innerHTML = '<div class="appointment-customer-result-empty">Escrib&iacute; al menos 2 caracteres para buscar.</div>'
        els.appointmentCustomerResults.hidden = false
        els.appointmentCustomerSearch.setAttribute('aria-expanded', 'true')
        return
      }
      const requestId = ++state.appointmentCustomerSearchRequest
      els.appointmentCustomerResults.innerHTML = '<div class="appointment-customer-result-empty">Buscando clientes...</div>'
      els.appointmentCustomerResults.hidden = false
      els.appointmentCustomerSearch.setAttribute('aria-expanded', 'true')
      const params = new URLSearchParams({ businessId: state.businessId, q: query, take: '12' })
      try {
        const customers = await getJson('/customers/search?' + params.toString())
        if (requestId !== state.appointmentCustomerSearchRequest) return
        renderAppointmentCustomerResults(customers, query)
      } catch (error) {
        if (requestId !== state.appointmentCustomerSearchRequest) return
        els.appointmentCustomerResults.innerHTML = '<div class="appointment-customer-result-empty">' + escapeHtml(error.message) + '</div>'
      }
    }

    function scheduleAppointmentCustomerSearch() {
      const query = els.appointmentCustomerSearch.value.trim()
      if (els.appointmentCustomer.value) {
        els.appointmentCustomer.value = ''
        els.appointmentCustomerName.value = ''
        els.appointmentCustomerPhone.value = ''
      }
      clearTimeout(state.appointmentCustomerSearchTimer)
      state.appointmentCustomerSearchTimer = setTimeout(() => loadAppointmentCustomerResults(query), 250)
    }

    async function loadAgenda(options = {}) {
      const monthRange = options.monthView
      const monthStart = new Date(state.agendaMonthDate.getFullYear(), state.agendaMonthDate.getMonth(), 1)
      const rangeStart = monthRange
        ? startOfMondayWeek(monthStart)
        : addDays(startOfDay(state.agendaSelectedDate), -14)
      const rangeEnd = addDays(rangeStart, 42)
      const params = new URLSearchParams({
        from: rangeStart.toISOString(),
        to: rangeEnd.toISOString()
      })

      if (state.businessId) {
        params.set('businessId', state.businessId)
      }

      if (els.agendaProfessional.value) {
        params.set('professionalId', els.agendaProfessional.value)
      }

      state.agendaAppointments = await getJson('/appointments?' + params.toString())
      state.agendaBlocks = await getJson('/schedule-blocks?' + params.toString())
      state.agendaLoadedRangeStart = new Date(rangeStart)
      state.agendaLoadedRangeEnd = new Date(rangeEnd)
      renderProfessionals()
      renderAgenda()
    }

    function renderAgenda() {
      clearAgendaPointerDrag()
      clearAgendaRangeSelection()
      renderAgendaMonth()
      renderAgendaBlockList()
      renderAgendaGrid()
      applyAgendaPermissions()
    }

    function renderAgendaMonth() {
      const monthDate = new Date(state.agendaMonthDate.getFullYear(), state.agendaMonthDate.getMonth(), 1)
      els.agendaMonthTitle.textContent = new Intl.DateTimeFormat('es-AR', {
        month: 'long',
        year: 'numeric'
      }).format(monthDate)

      const first = startOfWeek(monthDate)
      const selectedKey = dateKey(state.agendaSelectedDate)
      const appointmentKeys = new Set(filteredAgendaAppointments().map((appointment) => dateKey(new Date(appointment.startAt))))
      for (const block of filteredAgendaBlocksForRange(first, addDays(first, 42))) {
        const blockStart = startOfDay(new Date(block.startAt))
        const blockEnd = startOfDay(new Date(new Date(block.endAt).getTime() - 1))
        for (let day = new Date(blockStart); day <= blockEnd; day = addDays(day, 1)) {
          appointmentKeys.add(dateKey(day))
        }
      }
      const cells = ['D', 'L', 'M', 'M', 'J', 'V', 'S'].map((day) => {
        return '<div class="month-weekday">' + day + '</div>'
      })

      for (let index = 0; index < 42; index += 1) {
        const day = addDays(first, index)
        const key = dateKey(day)
        const className = [
          'month-day',
          day.getMonth() !== monthDate.getMonth() ? 'outside' : '',
          key === selectedKey ? 'selected' : '',
          appointmentKeys.has(key) ? 'has-items' : ''
        ].filter(Boolean).join(' ')

        cells.push('<button class="' + className + '" type="button" data-agenda-date="' + key + '">' + day.getDate() + '</button>')
      }

      els.agendaMonthGrid.innerHTML = cells.join('')
      for (const button of els.agendaMonthGrid.querySelectorAll('[data-agenda-date]')) {
        button.addEventListener('click', async () => {
          state.agendaSelectedDate = parseDateKey(button.dataset.agendaDate)
          state.agendaMonthDate = new Date(state.agendaSelectedDate)
          await loadAgenda()
        })
      }
    }

    function renderAgendaBlockList() {
      if (!els.agendaBlockList) return
      const rangeStart = state.agendaLoadedRangeStart || startOfWeek(state.agendaSelectedDate)
      const rangeEnd = state.agendaLoadedRangeEnd || addDays(rangeStart, 7)
      const blocks = filteredAgendaBlocksForRange(rangeStart, rangeEnd)
      if (!blocks.length) {
        els.agendaBlockList.innerHTML = ''
        return
      }

      els.agendaBlockList.innerHTML = blocks.slice(0, 8).map((block) => {
        const start = new Date(block.startAt)
        const end = new Date(block.endAt)
        const title = block.title || scheduleBlockReasonLabel(block.reason)
        const scope = block.professional?.name || 'Todo el salon'
        return '<article class="agenda-block-list-item">' +
          '<strong>' + escapeHtml(title) + '</strong>' +
          '<span>' + escapeHtml(scope + ' · ' + formatDateTime(start) + ' - ' + formatDateTime(end)) + '</span>' +
          '<button type="button" data-delete-block="' + block.id + '">Eliminar</button>' +
        '</article>'
      }).join('')

      for (const button of els.agendaBlockList.querySelectorAll('[data-delete-block]')) {
        button.addEventListener('click', () => deleteScheduleBlock(button.dataset.deleteBlock))
      }
    }

    function openAgendaBlockPopover(input = {}) {
      if (!canManageScheduleBlocks()) {
        showCrmToast('No tenes permiso para bloquear la agenda.', 'error')
        return
      }
      if (input.startAt) els.blockStart.value = toDatetimeLocalValue(input.startAt)
      if (input.endAt) els.blockEnd.value = toDatetimeLocalValue(input.endAt)
      if (input.professionalId !== undefined) els.blockProfessional.value = input.professionalId || ''
      state.agendaBlockOpen = true
      els.agendaBlockPopover.hidden = false
      els.blockStart.focus()
    }

    function closeAgendaBlockPopover() {
      state.agendaBlockOpen = false
      els.agendaBlockPopover.hidden = true
    }

    function renderAgendaGrid() {
      renderAgendaMobileThreeDay()
      return

      const step = Number(els.agendaStep.value || 15)
      const weekStart = startOfWeek(state.agendaSelectedDate)
      const days = Array.from({ length: 7 }, (_, index) => addDays(weekStart, index))
      const displayRange = getAgendaDisplayRange()
      const startMinute = displayRange.start
      const endMinute = displayRange.end
      const pixelsPerMinute = 28 / 15
      const rowHeight = step * pixelsPerMinute
      const rows = []

      els.agendaRange.textContent = formatAgendaRange(days[0], days[6])
      els.agendaToday.textContent = isDateInRange(new Date(), days[0], addDays(days[6], 1)) ? 'Hoy' : 'Ir a hoy'

      rows.push('<div class="agenda-grid" style="--agenda-row-height:' + rowHeight + 'px">')
      rows.push('<div class="agenda-corner"></div>')

      for (const day of days) {
        const todayClass = dateKey(day) === dateKey(new Date()) ? ' today' : ''
        rows.push('<button class="agenda-day-head' + todayClass + '" type="button" data-agenda-date="' + dateKey(day) + '">' + formatAgendaDayHeader(day) + '</button>')
      }

      for (let minute = startMinute; minute < endMinute; minute += step) {
        rows.push('<div class="agenda-time">' + formatMinuteLabel(minute) + '</div>')
        for (const day of days) {
          const closed = isClosedAgendaSlot(day, minute)
          const today = dateKey(day) === dateKey(new Date())
          rows.push('<div class="agenda-cell' + (today ? ' today' : '') + (closed ? ' closed' : '') + '" data-cell-date="' + dateKey(day) + '" data-cell-minute="' + minute + '"></div>')
        }
      }

      const now = new Date()
      const nowMinute = now.getHours() * 60 + now.getMinutes()
      if (isDateInRange(now, days[0], addDays(days[6], 1)) && nowMinute >= startMinute && nowMinute < endMinute) {
        const top = 38 + (nowMinute - startMinute) * pixelsPerMinute
        rows.push('<div class="agenda-now-line" data-time="' + escapeHtml(formatTimeOnly(now)) + '" style="top:' + top + 'px"></div>')
      }

      rows.push('</div>')
      els.agendaGridWrap.innerHTML = rows.join('')

      for (const button of els.agendaGridWrap.querySelectorAll('[data-agenda-date]')) {
        button.addEventListener('click', async () => {
          state.agendaSelectedDate = parseDateKey(button.dataset.agendaDate)
          state.agendaMonthDate = new Date(state.agendaSelectedDate)
          await loadAgenda()
        })
      }

      for (const cell of els.agendaGridWrap.querySelectorAll('[data-cell-date][data-cell-minute]')) {
        cell.addEventListener('click', (event) => {
          if (event.target.closest('.agenda-event')) return
          if (!canCreateAppointments()) {
            showCrmToast('No tenes permiso para cargar turnos.', 'error')
            return
          }
          openAppointmentDialog({
            date: parseDateKey(cell.dataset.cellDate),
            minute: Number(cell.dataset.cellMinute || startMinute)
          })
        })
      }

      const renderInput = {
        step,
        rowHeight,
        pixelsPerMinute,
        startMinute
      }
      renderAgendaBlocks(renderInput)
      renderAgendaEvents(renderInput)
      enableAgendaDragAndDrop()
    }

    function renderAgendaMobileThreeDay() {
      state.agendaProfessionalResizeObserver?.disconnect()
      state.agendaProfessionalResizeObserver = null
      const hourHeight = 88
      const viewDays = [1, 3, 7].includes(Number(state.agendaViewDays)) ? Number(state.agendaViewDays) : 1
      const professionalDayView = viewDays === 1 && !els.agendaProfessional.value
      const columnProfessionals = professionalDayView ? activeProfessionals() : []
      const startDate = startOfDay(state.agendaSelectedDate)
      const monthPanel = state.agendaMobileMonthOpen ? renderAgendaMobileMonthPanel() : ''
      const filtersPanel = state.agendaMobileFiltersOpen ? renderAgendaMobileFilterPanel() : ''
      const monthTitle = formatAgendaMobileTitle(state.agendaMobileMonthOpen ? state.agendaMonthDate : state.agendaSelectedDate)
      const filtersActive = state.agendaMobileFiltersOpen || Boolean(els.agendaProfessional.value || els.agendaService.value)
      const today = new Date()
      const currentDays = Array.from({ length: viewDays }, (_, index) => addDays(startDate, index))
      const displayRange = getAgendaDisplayRange(currentDays)
      const visibleHours = (displayRange.end - displayRange.start) / 60
      const visibleToday = currentDays.some((day) => dateKey(day) === dateKey(today))
      const bufferBefore = 7
      const bufferAfter = 21
      const renderedDays = professionalDayView
        ? currentDays
        : Array.from({ length: bufferBefore + viewDays + bufferAfter }, (_, index) => addDays(startDate, index - bufferBefore))
      const hourLabels = Array.from({ length: visibleHours }, (_, index) => {
        const hour = (displayRange.start / 60) + index
        return '<span class="agenda-gcal-hour-label" style="top:' + (index * hourHeight) + 'px">' + String(hour).padStart(2, '0') + ':00</span>'
      }).join('')
      const dayHeaders = professionalDayView
        ? columnProfessionals.map((professional, index) => renderAgendaProfessionalDayHeader(professional, index)).join('')
        : renderedDays.map((day) => renderAgendaMobileDayHeader(day)).join('')
      const dayColumns = professionalDayView
        ? columnProfessionals.map((professional) => renderAgendaProfessionalDayColumn(startDate, professional, hourHeight, displayRange)).join('')
        : renderedDays.map((day) => renderAgendaMobileDayColumn(day, hourHeight, displayRange)).join('')
      const todayIndex = professionalDayView ? -1 : renderedDays.findIndex((day) => dateKey(day) === dateKey(today))
      const nowMinute = today.getHours() * 60 + today.getMinutes()
      const nowTop = ((nowMinute - displayRange.start) / 60) * hourHeight
      const showNowLine = todayIndex >= 0 && nowMinute >= displayRange.start && nowMinute < displayRange.end

      els.agendaRange.textContent = formatAgendaRange(currentDays[0], currentDays[currentDays.length - 1])
      els.agendaToday.textContent = visibleToday ? 'Hoy' : 'Ir a hoy'
      els.agendaGridWrap.innerHTML =
        '<div class="agenda-gcal">' +
          '<header class="agenda-gcal-top">' +
            '<div class="agenda-gcal-nav">' +
              '<button class="agenda-gcal-icon" type="button" data-agenda-prev aria-label="Periodo anterior">&#8249;</button>' +
              '<button class="agenda-gcal-control" type="button" data-agenda-mobile-today>' + (visibleToday ? 'Hoy' : 'Ir a hoy') + '</button>' +
              '<button class="agenda-gcal-icon" type="button" data-agenda-next aria-label="Periodo siguiente">&#8250;</button>' +
            '</div>' +
            '<button class="agenda-gcal-icon" type="button" data-agenda-mobile-menu aria-label="Menu">☰</button>' +
            '<button class="agenda-gcal-title" type="button" data-agenda-mobile-month-toggle aria-expanded="' + String(state.agendaMobileMonthOpen) + '"><span>' + escapeHtml(monthTitle) + '</span><i aria-hidden="true"></i></button>' +
            '<div class="agenda-gcal-actions">' +
              '<select class="agenda-gcal-view-select" data-agenda-view-days aria-label="Dias visibles">' +
                [1, 3, 7].map((count) => '<option value="' + count + '"' + (count === viewDays ? ' selected' : '') + '>' + count + (count === 1 ? ' dia' : ' dias') + '</option>').join('') +
              '</select>' +
            '<button class="agenda-gcal-filter' + (filtersActive ? ' active' : '') + '" type="button" data-agenda-mobile-filters aria-expanded="' + String(state.agendaMobileFiltersOpen) + '">Filtros</button>' +
            (canManageScheduleBlocks() ? '<button class="agenda-gcal-control' + (state.agendaBlockOpen ? ' active' : '') + '" type="button" data-agenda-block-toggle>Bloquear</button>' : '') +
            '</div>' +
            '<button class="agenda-gcal-icon agenda-gcal-today" type="button" data-agenda-mobile-today aria-label="Hoy">' + today.getDate() + '</button>' +
          '</header>' +
          monthPanel +
          filtersPanel +
          '<div class="agenda-gcal-frame' + (professionalDayView ? ' agenda-gcal-professional-frame' : '') + '" data-agenda-mobile-frame data-agenda-base-index="' + (professionalDayView ? 0 : bufferBefore) + '" data-agenda-day-count="' + (professionalDayView ? columnProfessionals.length : renderedDays.length) + '" data-agenda-view-days="' + viewDays + '"' + (professionalDayView ? ' data-agenda-professional-columns="true"' : '') + ' style="--agenda-hour-height:' + hourHeight + 'px;--agenda-slot-height:' + (hourHeight / 2) + 'px;--agenda-visible-hours:' + visibleHours + ';--agenda-grid-height:' + (visibleHours * hourHeight) + 'px;--agenda-professional-count:' + Math.max(1, columnProfessionals.length) + '">' +
            '<div class="agenda-gcal-days-head">' +
              (professionalDayView ? renderAgendaProfessionalDateCorner(startDate) : '<div></div>') +
              '<div class="agenda-gcal-days-viewport" data-agenda-mobile-gesture>' +
                '<div class="agenda-gcal-days-track" data-agenda-mobile-track>' + dayHeaders + '</div>' +
              '</div>' +
            '</div>' +
            (professionalDayView
              ? '<div class="agenda-gcal-professional-scroll-row"><div></div><div class="agenda-gcal-professional-scroll" data-agenda-professional-scroll><div data-agenda-professional-scroll-spacer></div></div></div>'
              : '') +
            '<div class="agenda-gcal-scroll" data-agenda-mobile-scroll>' +
              '<div class="agenda-gcal-grid">' +
                '<div class="agenda-gcal-time-axis">' + hourLabels + '</div>' +
                '<div class="agenda-gcal-columns-viewport" data-agenda-mobile-gesture>' +
                  '<div class="agenda-gcal-columns-track" data-agenda-mobile-track>' +
                    dayColumns +
                    (showNowLine ? '<div class="agenda-gcal-now-line" style="top:' + nowTop + 'px;--agenda-now-index:' + todayIndex + '"></div>' : '') +
                  '</div>' +
                '</div>' +
              '</div>' +
            '</div>' +
          '</div>' +
          '<button class="agenda-gcal-fab" type="button" data-agenda-mobile-new aria-label="Nuevo turno">+</button>' +
        '</div>'

      bindAgendaMobileControls(hourHeight, displayRange)
      scrollAgendaMobileToWorkingTime(hourHeight, displayRange)
    }

    function renderAgendaProfessionalDateCorner(day) {
      const weekday = new Intl.DateTimeFormat('es-AR', { weekday: 'short' }).format(day)
      return '<div class="agenda-gcal-professional-date"><strong>' + escapeHtml(weekday) + '</strong><span>' + day.getDate() + '</span></div>'
    }

    function renderAgendaProfessionalDayHeader(professional, index) {
      const color = agendaProfessionalColor(professional.id, index)
      return '<button class="agenda-gcal-day-head agenda-gcal-professional-head" type="button" data-agenda-professional-column="' + professional.id + '" title="Ver solo la agenda de ' + escapeHtml(professional.name) + '">' +
        '<span class="agenda-dot" style="--agenda-color:' + color + '"></span>' +
        '<strong>' + escapeHtml(professional.name) + '</strong>' +
      '</button>'
    }

    function renderAgendaProfessionalDayColumn(day, professional, hourHeight, displayRange) {
      const key = dateKey(day)
      const slotCount = (displayRange.end - displayRange.start) / 30
      const cells = Array.from({ length: slotCount }, (_, slot) => {
        const minute = displayRange.start + slot * 30
        const closed = isClosedAgendaSlotForProfessional(day, minute, professional.id)
        return '<div class="agenda-gcal-hour-cell' + (closed ? ' closed' : '') + '" data-cell-date="' + key + '" data-cell-minute="' + minute + '" data-cell-professional-id="' + professional.id + '"></div>'
      }).join('')
      const appointments = filteredAgendaAppointmentsForRange(day, addDays(day, 1))
        .filter((appointment) => appointment.professionalId === professional.id)
      const eventLayout = buildAgendaEventLayout(appointments)
      const events = appointments
        .map((appointment) => renderAgendaMobileEvent(appointment, hourHeight, displayRange, eventLayout.get(appointment.id)))
        .join('')
      const blocks = filteredAgendaBlocksForRange(day, addDays(day, 1))
        .filter((block) => !block.professionalId || block.professionalId === professional.id)
        .map((block) => renderAgendaMobileBlock(block, day, hourHeight, displayRange))
        .join('')
      const now = new Date()
      const nowMinute = now.getHours() * 60 + now.getMinutes()
      const nowLine = dateKey(day) === dateKey(now) && nowMinute >= displayRange.start && nowMinute < displayRange.end
        ? '<div class="agenda-gcal-now-line agenda-gcal-professional-now-line" style="top:' + (((nowMinute - displayRange.start) / 60) * hourHeight) + 'px"></div>'
        : ''
      return '<div class="agenda-gcal-day-column agenda-gcal-professional-column" data-gcal-day="' + key + '" data-gcal-professional="' + professional.id + '">' + cells + events + blocks + nowLine + '</div>'
    }

    function renderAgendaMobileDayHeader(day) {
      const today = new Date()
      const todayKey = dateKey(today)
      const key = dateKey(day)
      const weekday = new Intl.DateTimeFormat('es-AR', { weekday: 'short' }).format(day)
      return '<button class="agenda-gcal-day-head' + (key === todayKey ? ' today' : '') + '" type="button" data-agenda-date="' + key + '">' +
        '<strong>' + escapeHtml(weekday) + '</strong>' +
        '<span>' + day.getDate() + '</span>' +
      '</button>'
    }

    function renderAgendaMobileDayColumn(day, hourHeight, displayRange) {
      const key = dateKey(day)
      const slotCount = (displayRange.end - displayRange.start) / 30
      const cells = Array.from({ length: slotCount }, (_, slot) => {
        const minute = displayRange.start + slot * 30
        const closed = isClosedAgendaSlot(day, minute)
        return '<div class="agenda-gcal-hour-cell' + (closed ? ' closed' : '') + '" data-cell-date="' + key + '" data-cell-minute="' + minute + '"></div>'
      }).join('')
      const dayAppointments = filteredAgendaAppointmentsForRange(day, addDays(day, 1))
      const eventLayout = buildAgendaEventLayout(dayAppointments)
      const events = dayAppointments
        .map((appointment) => renderAgendaMobileEvent(appointment, hourHeight, displayRange, eventLayout.get(appointment.id)))
        .join('')
      const dayBlocks = filteredAgendaBlocksForRange(day, addDays(day, 1))
        .map((block) => renderAgendaMobileBlock(block, day, hourHeight, displayRange))
        .join('')
      const actionRail = Number(state.agendaViewDays) > 1 && (canCreateAppointments() || canManageScheduleBlocks())
        ? '<button class="agenda-gcal-action-rail" type="button" data-agenda-action-rail data-cell-date="' + key + '" data-range-start="' + displayRange.start + '" data-range-end="' + displayRange.end + '" aria-label="Elegir un horario aunque haya turnos"><span class="agenda-action-rail-marker" aria-hidden="true">+</span></button>'
        : ''
      return '<div class="agenda-gcal-day-column' + (actionRail ? ' has-action-rail' : '') + '" data-gcal-day="' + key + '">' + cells + events + dayBlocks + actionRail + '</div>'
    }

    function renderAgendaMobileEvent(appointment, hourHeight, displayRange, placement = { column: 0, columns: 1 }) {
      const start = new Date(appointment.startAt)
      const duration = appointment.totalDurationMinutes || appointment.service?.duration || 30
      const startMinute = start.getHours() * 60 + start.getMinutes()
      const visibleStartMinute = Math.max(startMinute, displayRange.start)
      const visibleEndMinute = Math.min(startMinute + duration, displayRange.end)
      if (visibleEndMinute <= visibleStartMinute) return ''
      const top = ((visibleStartMinute - displayRange.start) / 60) * hourHeight + 2
      const height = Math.max(34, ((visibleEndMinute - visibleStartMinute) / 60) * hourHeight - 4)
      const professionalIndex = activeProfessionals().findIndex((item) => item.id === appointment.professionalId)
      const color = agendaProfessionalColor(appointment.professionalId, professionalIndex)
      const noShow = appointment.status === 'NO_SHOW'
      const pending = state.agendaPendingAppointmentIds.has(appointment.id)
      const columns = Math.max(1, placement?.columns || 1)
      const column = Math.max(0, placement?.column || 0)
      const left = 'calc(' + ((column * 100) / columns) + '% + 4px)'
      const width = 'calc(' + (100 / columns) + '% - 8px)'
      const customer = appointment.customer?.name || 'Cliente'
      const service = appointmentServiceLabel(appointment)
      const professional = appointment.professional?.name || 'Profesional'
      const time = formatTimeOnly(start)
      const depositIndicator = agendaDepositIndicator(appointment)
      const depositClass = depositIndicator ? ' has-deposit' : ''
      const depositStyle = depositIndicator ? ';--agenda-deposit-color:' + depositIndicator.color : ''
      const depositTitle = depositIndicator ? ' - ' + depositIndicator.label : ''
      const origin = appointmentOriginMeta(appointment.origin)
      return '<article class="agenda-gcal-event' + depositClass + (noShow ? ' no-show' : '') + (pending ? ' is-pending' : '') + '" data-appointment-id="' + appointment.id + '" data-overlap-count="' + columns + '" style="top:' + top + 'px;height:' + height + 'px;left:' + left + ';right:auto;width:' + width + ';--agenda-event-color:' + color + depositStyle + '" title="' + escapeHtml(time + ' - ' + customer + ' - ' + service + ' con ' + professional + ' - ' + origin.label + depositTitle) + '">' +
        '<button class="agenda-gcal-event-main" type="button" data-agenda-edit-appointment>' +
          '<strong>' + escapeHtml(service) + '</strong>' +
          '<span>' + appointmentOriginBadgeHtml(origin) + ' ' + escapeHtml(customer + (noShow ? ' - Ausente' : '')) + '</span>' +
          '<span class="agenda-gcal-event-professional">' + escapeHtml(professional) + '</span>' +
        '</button>' +
        (canCreateAppointments() ? '<button class="agenda-gcal-event-add" type="button" data-agenda-new-at aria-label="Crear otro turno a las ' + escapeHtml(time) + '" title="Crear otro turno en este horario"><span aria-hidden="true">+</span><span class="agenda-gcal-event-add-label">Otro</span></button>' : '') +
      '</article>'
    }

    function agendaDepositIndicator(appointment) {
      const status = appointment.bookingDeposit?.status
      if (status === 'PENDING_PROOF') {
        return { color: '#dc2626', label: 'Esperando comprobante' }
      }
      if (status === 'PROOF_RECEIVED') {
        return { color: '#eab308', label: 'Comprobante pendiente del staff' }
      }
      if (status === 'APPROVED') {
        return { color: '#16a34a', label: 'Comprobante verificado' }
      }
      if (appointment.manualDepositPaid === true) {
        return {
          color: '#16a34a',
          label: appointment.manualDepositAmount
            ? 'Seña registrada: ' + formatCurrency(appointment.manualDepositAmount)
            : 'Seña registrada'
        }
      }
      return null
    }

    function appointmentOriginMeta(origin) {
      if (origin === 'BOT') return { code: 'B', label: 'Bot de WhatsApp', className: 'origin-bot' }
      if (origin === 'WEB') return { code: 'W', label: 'Sitio web', className: 'origin-web' }
      if (origin === 'MANUAL') return { code: 'M', label: 'Carga manual', className: 'origin-manual' }
      return { code: '?', label: 'Origen anterior sin identificar', className: 'origin-unknown' }
    }

    function appointmentOriginBadgeHtml(origin) {
      return '<span class="appointment-origin-badge ' + origin.className + '" title="' + escapeHtml(origin.label) + '" aria-label="' + escapeHtml(origin.label) + '">' + origin.code + '</span>'
    }

    function renderAgendaMobileBlock(block, day, hourHeight, displayRange) {
      const blockStart = new Date(block.startAt)
      const blockEnd = new Date(block.endAt)
      const dayStart = startOfDay(day)
      const dayEnd = addDays(dayStart, 1)
      const segmentStart = new Date(Math.max(blockStart.getTime(), dayStart.getTime()))
      const segmentEnd = new Date(Math.min(blockEnd.getTime(), dayEnd.getTime()))
      if (segmentEnd <= segmentStart) return ''

      const segmentStartMinute = blockStart <= dayStart ? 0 : segmentStart.getHours() * 60 + segmentStart.getMinutes()
      const segmentEndMinute = blockEnd >= dayEnd ? 24 * 60 : segmentEnd.getHours() * 60 + segmentEnd.getMinutes()
      const visibleStartMinute = Math.max(segmentStartMinute, displayRange.start)
      const visibleEndMinute = Math.min(segmentEndMinute, displayRange.end)
      if (visibleEndMinute <= visibleStartMinute) return ''
      const duration = Math.max(15, visibleEndMinute - visibleStartMinute)
      const top = ((visibleStartMinute - displayRange.start) / 60) * hourHeight + 2
      const height = Math.max(34, (duration / 60) * hourHeight - 4)
      const coversDayStart = blockStart <= dayStart
      const coversDayEnd = blockEnd >= dayEnd
      const timeLabel = coversDayStart && coversDayEnd
        ? 'Todo el d&iacute;a'
        : (coversDayStart ? '00:00' : formatTimeOnly(segmentStart)) + ' - ' + (coversDayEnd ? '24:00' : formatTimeOnly(segmentEnd))
      const scope = block.professional?.name || 'Todo el sal&oacute;n'
      return '<button class="agenda-gcal-block" type="button" data-block-id="' + block.id + '" style="top:' + top + 'px;height:' + height + 'px">' +
        '<strong>' + escapeHtml(block.title || scheduleBlockReasonLabel(block.reason)) + '</strong>' +
        '<span>' + timeLabel + '</span>' +
        '<span>' + escapeHtml(scope) + '</span>' +
      '</button>'
    }

    function renderAgendaMobileMonthPanel() {
      const monthDate = new Date(state.agendaMonthDate.getFullYear(), state.agendaMonthDate.getMonth(), 1)
      const first = startOfMondayWeek(monthDate)
      const selectedKey = dateKey(state.agendaSelectedDate)
      const appointmentKeys = new Set(filteredAgendaAppointmentsForRange(first, addDays(first, 42)).map((appointment) => dateKey(new Date(appointment.startAt))))
      const cells = ['L', 'M', 'M', 'J', 'V', 'S', 'D'].map((day) => '<div class="agenda-gcal-month-weekday">' + day + '</div>')
      for (let index = 0; index < 42; index += 1) {
        const day = addDays(first, index)
        const key = dateKey(day)
        const className = [
          'agenda-gcal-month-day',
          day.getMonth() !== monthDate.getMonth() ? 'outside' : '',
          key === selectedKey ? 'selected' : '',
          appointmentKeys.has(key) ? 'has-items' : ''
        ].filter(Boolean).join(' ')
        cells.push('<button class="' + className + '" type="button" data-agenda-mobile-date="' + key + '">' + day.getDate() + '</button>')
      }

      const monthButtons = Array.from({ length: 7 }, (_, index) => {
        const date = new Date(monthDate.getFullYear(), monthDate.getMonth() - 3 + index, 1)
        const active = date.getMonth() === monthDate.getMonth() && date.getFullYear() === monthDate.getFullYear()
        return '<button class="' + (active ? 'active' : '') + '" type="button" data-agenda-mobile-month="' + dateKey(date) + '">' + escapeHtml(new Intl.DateTimeFormat('es-AR', { month: 'short' }).format(date)) + '</button>'
      }).join('')

      return '<section class="agenda-gcal-month-panel">' +
        '<div class="agenda-gcal-month-grid">' + cells.join('') + '</div>' +
        '<div class="agenda-gcal-month-strip">' + monthButtons + '</div>' +
      '</section>'
    }

    function renderAgendaMobileFilterPanel() {
      const selectedProfessional = els.agendaProfessional.value || ''
      const selectedService = els.agendaService.value || ''
      const professionalOptions = ['<option value="">Todos los profesionales</option>']
        .concat(activeProfessionals().map((professional) => {
          return '<option value="' + professional.id + '"' + (professional.id === selectedProfessional ? ' selected' : '') + '>' + escapeHtml(professional.name) + '</option>'
        }))
        .join('')
      const serviceOptions = ['<option value="">Todos los servicios</option>']
        .concat(bookableServices().map((service) => {
          return '<option value="' + service.id + '"' + (service.id === selectedService ? ' selected' : '') + '>' + escapeHtml(serviceCatalogLabel(service)) + '</option>'
        }))
        .join('')

      return '<section class="agenda-gcal-filter-panel">' +
        '<label>Profesional<select data-agenda-mobile-professional>' + professionalOptions + '</select></label>' +
        '<label>Servicio<select data-agenda-mobile-service>' + serviceOptions + '</select></label>' +
      '</section>'
    }

    function agendaRangeCellContext(cell) {
      return {
        dateKey: cell.dataset.cellDate,
        columnProfessionalId: cell.dataset.cellProfessionalId || '',
        professionalId: cell.dataset.cellProfessionalId || els.agendaProfessional.value || '',
        minute: Number(cell.dataset.cellMinute || 0)
      }
    }

    function startAgendaRangeSelection(pointerEvent, cell) {
      if (pointerEvent.pointerType === 'touch') return
      if (pointerEvent.button !== 0) return
      if (pointerEvent.target.closest('[data-appointment-id], [data-block-id], .agenda-range-actions')) return
      if (!canCreateAppointments() && !canManageScheduleBlocks()) {
        showCrmToast('No tenes permiso para agendar ni bloquear horarios.', 'error')
        return
      }

      clearAgendaRangeSelection()
      const context = agendaRangeCellContext(cell)
      state.agendaRangePointer = {
        pointerId: pointerEvent.pointerId,
        startX: pointerEvent.clientX,
        startY: pointerEvent.clientY,
        dateKey: context.dateKey,
        columnProfessionalId: context.columnProfessionalId,
        professionalId: context.professionalId,
        startMinute: context.minute,
        currentMinute: context.minute,
        anchorElement: null,
        dragging: false
      }

      window.addEventListener('pointermove', updateAgendaRangeSelection, true)
      window.addEventListener('pointerup', finishAgendaRangeSelection, true)
      window.addEventListener('pointercancel', cancelAgendaRangeSelection, true)
      window.addEventListener('blur', cancelAgendaRangeSelection)
    }

    function updateAgendaRangeSelection(pointerEvent) {
      const pointer = state.agendaRangePointer
      if (!pointer || pointerEvent.pointerId !== pointer.pointerId) return

      const deltaX = pointerEvent.clientX - pointer.startX
      const deltaY = pointerEvent.clientY - pointer.startY
      const moved = Math.hypot(deltaX, deltaY)
      if (!pointer.dragging) {
        if (moved < 10) return
        if (Math.abs(deltaX) > Math.abs(deltaY) * 1.15) {
          clearAgendaRangePointer()
          return
        }
        pointer.dragging = true
      }
      pointerEvent.preventDefault()

      const cell = document.elementsFromPoint(pointerEvent.clientX, pointerEvent.clientY)
        .map((element) => element.closest?.('[data-cell-date][data-cell-minute]'))
        .find((candidate) => candidate && els.agendaGridWrap.contains(candidate))
      if (!cell) return

      const context = agendaRangeCellContext(cell)
      if (context.dateKey !== pointer.dateKey || context.columnProfessionalId !== pointer.columnProfessionalId) return

      pointer.currentMinute = context.minute
      state.agendaRangeSelection = {
        dateKey: pointer.dateKey,
        columnProfessionalId: pointer.columnProfessionalId,
        professionalId: pointer.professionalId,
        startMinute: Math.min(pointer.startMinute, pointer.currentMinute),
        endMinute: Math.max(pointer.startMinute, pointer.currentMinute) + 30,
        anchorElement: pointer.anchorElement
      }
      renderAgendaRangeSelection(false)
    }

    function finishAgendaRangeSelection(pointerEvent) {
      const pointer = state.agendaRangePointer
      if (!pointer || pointerEvent.pointerId !== pointer.pointerId) return
      const wasDragging = pointer.dragging
      clearAgendaRangePointer()
      if (!wasDragging) return

      pointerEvent.preventDefault()
      state.agendaDidDrag = true
      renderAgendaRangeSelection(true)
      setTimeout(() => {
        state.agendaDidDrag = false
      }, 200)
    }

    function cancelAgendaRangeSelection() {
      clearAgendaRangeSelection()
    }

    function clearAgendaRangePointer() {
      window.removeEventListener('pointermove', updateAgendaRangeSelection, true)
      window.removeEventListener('pointerup', finishAgendaRangeSelection, true)
      window.removeEventListener('pointercancel', cancelAgendaRangeSelection, true)
      window.removeEventListener('blur', cancelAgendaRangeSelection)
      state.agendaRangePointer = null
    }

    function selectAgendaCellRange(cell, anchorElement = cell) {
      const context = agendaRangeCellContext(cell)
      state.agendaRangeSelection = {
        dateKey: context.dateKey,
        columnProfessionalId: context.columnProfessionalId,
        professionalId: context.professionalId,
        startMinute: context.minute,
        endMinute: context.minute + 30,
        anchorElement
      }
      renderAgendaRangeSelection(true)
    }

    function selectAgendaOccupiedRange(eventNode, appointment) {
      clearAgendaRangeSelection()
      const start = new Date(appointment.startAt)
      const professionalColumn = eventNode.closest('[data-gcal-professional]')
      state.agendaRangeSelection = {
        dateKey: dateKey(start),
        columnProfessionalId: professionalColumn?.dataset.gcalProfessional || '',
        professionalId: professionalColumn?.dataset.gcalProfessional || els.agendaProfessional.value || '',
        startMinute: start.getHours() * 60 + start.getMinutes(),
        endMinute: start.getHours() * 60 + start.getMinutes() + 30,
        anchorElement: eventNode.querySelector('[data-agenda-new-at]'),
        anchorAppointmentId: appointment.id,
        additionalAtOccupiedTime: true
      }
      renderAgendaRangeSelection(true)
    }

    function agendaActionRailCellAtPointer(rail, clientY) {
      const column = rail.closest('[data-gcal-day]')
      if (!column) return null
      const rect = column.getBoundingClientRect()
      const rangeStart = Number(rail.dataset.rangeStart || 0)
      const rangeEnd = Number(rail.dataset.rangeEnd || 24 * 60)
      const relativeY = Math.max(0, Math.min(rect.height - 1, clientY - rect.top))
      const slotHeight = rect.height / Math.max(1, (rangeEnd - rangeStart) / 30)
      const minute = Math.min(rangeEnd - 30, rangeStart + Math.floor(relativeY / slotHeight) * 30)
      return column.querySelector('[data-cell-date="' + rail.dataset.cellDate + '"][data-cell-minute="' + minute + '"]')
    }

    function positionAgendaActionRailMarker(rail, cell) {
      const marker = rail.querySelector('.agenda-action-rail-marker')
      if (!marker || !cell) return null
      const rangeStart = Number(rail.dataset.rangeStart || 0)
      const rangeEnd = Number(rail.dataset.rangeEnd || 24 * 60)
      const minute = Number(cell.dataset.cellMinute || rangeStart)
      const railHeight = rail.getBoundingClientRect().height
      const slotHeight = railHeight / Math.max(1, (rangeEnd - rangeStart) / 30)
      marker.style.height = slotHeight + 'px'
      marker.style.top = (((minute - rangeStart) / 30) * slotHeight) + 'px'
      marker.title = formatMinuteLabel(minute)
      return marker
    }

    function renderAgendaRangeSelection(showActions) {
      document.querySelector('.agenda-range-actions')?.remove()
      els.agendaGridWrap.querySelectorAll('.agenda-range-anchor').forEach((eventNode) => eventNode.classList.remove('agenda-range-anchor'))
      els.agendaGridWrap.querySelectorAll('[data-agenda-action-rail].active').forEach((rail) => rail.classList.remove('active'))
      for (const cell of els.agendaGridWrap.querySelectorAll('.agenda-range-selected, .agenda-range-first, .agenda-range-last')) {
        cell.classList.remove('agenda-range-selected', 'agenda-range-first', 'agenda-range-last')
      }

      const selection = state.agendaRangeSelection
      if (!selection) return
      const cells = Array.from(els.agendaGridWrap.querySelectorAll('[data-cell-date][data-cell-minute]'))
        .filter((cell) => {
          const minute = Number(cell.dataset.cellMinute)
          return cell.dataset.cellDate === selection.dateKey &&
            (cell.dataset.cellProfessionalId || '') === selection.columnProfessionalId &&
            minute < selection.endMinute && minute + 30 > selection.startMinute
        })
        .sort((left, right) => Number(left.dataset.cellMinute) - Number(right.dataset.cellMinute))
      if (!cells.length) return

      cells.forEach((cell) => cell.classList.add('agenda-range-selected'))
      cells[0].classList.add('agenda-range-first')
      cells[cells.length - 1].classList.add('agenda-range-last')
      if (selection.anchorAppointmentId) {
        els.agendaGridWrap.querySelector('[data-appointment-id="' + selection.anchorAppointmentId + '"]')?.classList.add('agenda-range-anchor')
      }
      selection.anchorElement?.closest?.('[data-agenda-action-rail]')?.classList.add('active')
      if (!showActions) return

      const actions = document.createElement('div')
      actions.className = 'agenda-range-actions'
      actions.setAttribute('role', 'menu')
      actions.innerHTML = '<strong>' + formatMinuteLabel(selection.startMinute) + ' - ' + formatMinuteLabel(selection.endMinute) + '</strong>' +
        (canCreateAppointments() ? '<button type="button" role="menuitem" data-agenda-range-action="appointment">Agendar</button>' : '') +
        (canManageScheduleBlocks() ? '<button type="button" role="menuitem" data-agenda-range-action="block">Bloquear horario</button>' : '')
      document.body.appendChild(actions)

      const anchor = selection.anchorElement?.isConnected ? selection.anchorElement : cells[cells.length - 1]
      const anchorRect = anchor.getBoundingClientRect()
      const actionsRect = actions.getBoundingClientRect()
      const left = Math.max(8, Math.min(anchorRect.left + 10, window.innerWidth - actionsRect.width - 8))
      const below = anchorRect.bottom + 6
      const top = below + actionsRect.height <= window.innerHeight - 8
        ? below
        : Math.max(8, anchorRect.top - actionsRect.height - 6)
      actions.style.left = left + 'px'
      actions.style.top = top + 'px'

      actions.querySelector('[data-agenda-range-action="appointment"]')?.addEventListener('click', () => {
        const selected = { ...state.agendaRangeSelection }
        clearAgendaRangeSelection()
        openAppointmentDialog({
          date: parseDateKey(selected.dateKey),
          minute: selection.startMinute,
          professionalId: selected.professionalId || undefined,
          additionalAtOccupiedTime: selected.additionalAtOccupiedTime === true
        })
      })
      actions.querySelector('[data-agenda-range-action="block"]')?.addEventListener('click', () => {
        const selected = { ...state.agendaRangeSelection }
        const dayStart = startOfDay(parseDateKey(selected.dateKey))
        clearAgendaRangeSelection()
        openAgendaBlockPopover({
          startAt: addMinutes(dayStart, selected.startMinute),
          endAt: addMinutes(dayStart, selected.endMinute),
          professionalId: selected.professionalId
        })
      })
      setTimeout(() => document.addEventListener('pointerdown', handleAgendaRangeOutsidePointer, true), 0)
    }

    function handleAgendaRangeOutsidePointer(event) {
      if (event.target.closest('.agenda-range-actions, [data-cell-date][data-cell-minute]')) return
      clearAgendaRangeSelection()
    }

    function clearAgendaRangeSelection() {
      clearAgendaRangePointer()
      document.removeEventListener('pointerdown', handleAgendaRangeOutsidePointer, true)
      document.querySelector('.agenda-range-actions')?.remove()
      els.agendaGridWrap.querySelectorAll('.agenda-range-anchor').forEach((eventNode) => eventNode.classList.remove('agenda-range-anchor'))
      els.agendaGridWrap.querySelectorAll('[data-agenda-action-rail].active').forEach((rail) => rail.classList.remove('active'))
      for (const cell of els.agendaGridWrap.querySelectorAll('.agenda-range-selected, .agenda-range-first, .agenda-range-last')) {
        cell.classList.remove('agenda-range-selected', 'agenda-range-first', 'agenda-range-last')
      }
      state.agendaRangeSelection = null
    }

    function bindAgendaMobileControls(hourHeight, displayRange) {
      els.agendaGridWrap.querySelector('[data-agenda-mobile-menu]')?.addEventListener('click', openMobileDrawer)
      els.agendaGridWrap.querySelector('[data-agenda-prev]')?.addEventListener('click', async () => {
        state.agendaSelectedDate = addDays(state.agendaSelectedDate, -state.agendaViewDays)
        state.agendaMonthDate = new Date(state.agendaSelectedDate)
        await loadAgenda()
      })
      els.agendaGridWrap.querySelector('[data-agenda-next]')?.addEventListener('click', async () => {
        state.agendaSelectedDate = addDays(state.agendaSelectedDate, state.agendaViewDays)
        state.agendaMonthDate = new Date(state.agendaSelectedDate)
        await loadAgenda()
      })
      els.agendaGridWrap.querySelector('[data-agenda-view-days]')?.addEventListener('change', (event) => {
        state.agendaViewDays = Number(event.target.value || 1)
        renderAgenda()
      })
      els.agendaGridWrap.querySelector('[data-agenda-block-toggle]')?.addEventListener('click', openAgendaBlockPopover)
      els.agendaGridWrap.querySelector('[data-agenda-mobile-month-toggle]')?.addEventListener('click', async () => {
        state.agendaMobileMonthOpen = !state.agendaMobileMonthOpen
        if (state.agendaMobileMonthOpen) state.agendaMobileFiltersOpen = false
        if (state.agendaMobileMonthOpen) {
          await loadAgenda({ monthView: true })
        } else {
          renderAgenda()
        }
      })
      els.agendaGridWrap.querySelector('[data-agenda-mobile-filters]')?.addEventListener('click', () => {
        state.agendaMobileFiltersOpen = !state.agendaMobileFiltersOpen
        if (state.agendaMobileFiltersOpen) state.agendaMobileMonthOpen = false
        renderAgenda()
      })
      els.agendaGridWrap.querySelector('[data-agenda-mobile-today]')?.addEventListener('click', async () => {
        state.agendaSelectedDate = new Date()
        state.agendaMonthDate = new Date()
        state.agendaMobileMonthOpen = false
        await loadAgenda()
      })
      els.agendaGridWrap.querySelector('[data-agenda-mobile-new]')?.addEventListener('click', () => openAppointmentDialog({ date: state.agendaSelectedDate }))

      for (const button of els.agendaGridWrap.querySelectorAll('[data-agenda-date], [data-agenda-mobile-date]')) {
        button.addEventListener('click', async () => {
          if (state.agendaDidDrag) return
          state.agendaSelectedDate = parseDateKey(button.dataset.agendaDate || button.dataset.agendaMobileDate)
          state.agendaMonthDate = new Date(state.agendaSelectedDate)
          state.agendaMobileMonthOpen = false
          await loadAgenda()
        })
      }

      for (const button of els.agendaGridWrap.querySelectorAll('[data-agenda-mobile-month]')) {
        button.addEventListener('click', async () => {
          state.agendaMonthDate = parseDateKey(button.dataset.agendaMobileMonth)
          await loadAgenda({ monthView: true })
        })
      }

      els.agendaGridWrap.querySelector('[data-agenda-mobile-professional]')?.addEventListener('change', async (event) => {
        els.agendaProfessional.value = event.target.value || ''
        renderAgendaProfessionalControls()
        await loadAgenda()
      })

      els.agendaGridWrap.querySelector('[data-agenda-mobile-service]')?.addEventListener('change', (event) => {
        els.agendaService.value = event.target.value || ''
        renderAgenda()
      })

      for (const cell of els.agendaGridWrap.querySelectorAll('[data-cell-date][data-cell-minute]')) {
        cell.addEventListener('pointerdown', (event) => startAgendaRangeSelection(event, cell))
        cell.addEventListener('click', () => {
          if (state.agendaDidDrag) return
          if (!canCreateAppointments() && !canManageScheduleBlocks()) {
            showCrmToast('No tenes permiso para agendar ni bloquear horarios.', 'error')
            return
          }
          selectAgendaCellRange(cell)
        })
      }

      for (const rail of els.agendaGridWrap.querySelectorAll('[data-agenda-action-rail]')) {
        rail.addEventListener('pointermove', (event) => {
          const cell = agendaActionRailCellAtPointer(rail, event.clientY)
          positionAgendaActionRailMarker(rail, cell)
        })
        rail.addEventListener('pointerleave', () => {
          if (!state.agendaRangePointer && !rail.classList.contains('active')) {
            rail.querySelector('.agenda-action-rail-marker')?.removeAttribute('style')
          }
        })
        rail.addEventListener('pointerdown', (event) => {
          const cell = agendaActionRailCellAtPointer(rail, event.clientY)
          if (!cell) return
          const marker = positionAgendaActionRailMarker(rail, cell)
          startAgendaRangeSelection(event, cell)
          if (state.agendaRangePointer) state.agendaRangePointer.anchorElement = marker
        })
        rail.addEventListener('click', (event) => {
          if (state.agendaDidDrag) return
          const cell = agendaActionRailCellAtPointer(rail, event.clientY)
          if (!cell) return
          const marker = positionAgendaActionRailMarker(rail, cell)
          selectAgendaCellRange(cell, marker)
        })
      }

      for (const eventNode of els.agendaGridWrap.querySelectorAll('[data-appointment-id]')) {
        const appointment = state.agendaAppointments.find((item) => item.id === eventNode.dataset.appointmentId)
        eventNode.addEventListener('click', (event) => {
          event.stopPropagation()
          if (event.target.closest('[data-agenda-new-at]')) return
          if (state.agendaDidDrag) return
          if (appointment) openAppointmentDialog({ appointment })
        })
        eventNode.querySelector('[data-agenda-new-at]')?.addEventListener('click', (event) => {
          event.stopPropagation()
          if (!appointment || state.agendaDidDrag) return
          if (!canCreateAppointments()) {
            showCrmToast('No tenes permiso para cargar turnos.', 'error')
            return
          }
          selectAgendaOccupiedRange(eventNode, appointment)
        })
        eventNode.addEventListener('pointerdown', (event) => {
          if (event.target.closest('[data-agenda-new-at]')) return
          startAgendaPointerDrag(event, eventNode, eventNode.dataset.appointmentId)
        })
      }

      for (const button of els.agendaGridWrap.querySelectorAll('[data-block-id]')) {
        button.addEventListener('click', (event) => {
          event.stopPropagation()
          deleteScheduleBlock(button.dataset.blockId)
        })
      }

      const frame = els.agendaGridWrap.querySelector('[data-agenda-mobile-frame]')
      const currentScroll = els.agendaGridWrap.querySelector('[data-agenda-mobile-scroll]')
      if (currentScroll) {
        currentScroll.addEventListener('scroll', () => {
          state.agendaMobileScrollMinute = displayRange.start + (currentScroll.scrollTop / hourHeight) * 60
        }, { passive: true })
      }

      if (frame) {
        const baseIndex = Number(frame.dataset.agendaBaseIndex || 0)
        const dayCount = Number(frame.dataset.agendaDayCount || 0)
        const viewDays = Number(frame.dataset.agendaViewDays || 1)
        const columnsViewport = frame.querySelector('.agenda-gcal-columns-viewport')
        const daysViewport = frame.querySelector('.agenda-gcal-days-viewport')
        if (frame.dataset.agendaProfessionalColumns === 'true') {
          const professionalScrollbar = frame.querySelector('[data-agenda-professional-scroll]')
          const professionalScrollSpacer = frame.querySelector('[data-agenda-professional-scroll-spacer]')
          const syncProfessionalColumnWidths = () => {
            const viewportWidth = columnsViewport?.clientWidth || 0
            if (viewportWidth < 2) return
            const minimumWidth = window.matchMedia('(max-width: 760px)').matches ? 240 : 260
            const columnWidth = Math.max(minimumWidth, viewportWidth / Math.max(1, dayCount))
            frame.style.setProperty('--agenda-day-width', columnWidth + 'px')
            if (professionalScrollSpacer) professionalScrollSpacer.style.width = (columnWidth * dayCount) + 'px'
          }
          let syncingProfessionalScroll = false
          const syncHorizontalScroll = (source) => {
            if (!source || syncingProfessionalScroll) return
            syncingProfessionalScroll = true
            for (const target of [daysViewport, columnsViewport, professionalScrollbar]) {
              if (target && target !== source) target.scrollLeft = source.scrollLeft
            }
            requestAnimationFrame(() => {
              syncingProfessionalScroll = false
            })
          }
          columnsViewport?.addEventListener('scroll', () => syncHorizontalScroll(columnsViewport), { passive: true })
          professionalScrollbar?.addEventListener('scroll', () => syncHorizontalScroll(professionalScrollbar), { passive: true })
          for (const button of frame.querySelectorAll('[data-agenda-professional-column]')) {
            button.addEventListener('click', async () => {
              els.agendaProfessional.value = button.dataset.agendaProfessionalColumn || ''
              renderAgendaProfessionalControls()
              await loadAgenda()
            })
          }
          if (columnsViewport && typeof ResizeObserver !== 'undefined') {
            state.agendaProfessionalResizeObserver = new ResizeObserver(syncProfessionalColumnWidths)
            state.agendaProfessionalResizeObserver.observe(columnsViewport)
          }
          requestAnimationFrame(() => {
            syncProfessionalColumnWidths()
            requestAnimationFrame(syncProfessionalColumnWidths)
          })
          return
        }
        const applyTransform = (value) => {
          state.agendaMobileCurrentTranslate = value
          frame.style.setProperty('--agenda-mobile-x', value + 'px')
        }
        const syncMeasurements = () => {
          const viewportWidth = columnsViewport?.clientWidth || frame.clientWidth || 0
          if (viewportWidth < 2) return
          const dayWidth = viewportWidth / viewDays
          state.agendaMobileDayWidth = dayWidth
          state.agendaMobileBaseIndex = baseIndex
          frame.style.setProperty('--agenda-day-width', dayWidth + 'px')
          applyTransform(-baseIndex * dayWidth)
        }
        const finishDrag = (dayOffset) => {
          if (!state.agendaMobileDayWidth || state.agendaMobilePaging) return
          const maxOffset = Math.max(0, dayCount - baseIndex - viewDays)
          const safeOffset = Math.max(-baseIndex, Math.min(maxOffset, dayOffset))
          const targetTranslate = -(baseIndex + safeOffset) * state.agendaMobileDayWidth
          frame.classList.add('is-snapping')
          applyTransform(targetTranslate)
          window.setTimeout(async () => {
            frame.classList.remove('is-snapping')
            if (!safeOffset) {
              window.setTimeout(() => {
                state.agendaDidDrag = false
              }, 80)
              return
            }
            state.agendaMobilePaging = true
            if (currentScroll) {
              state.agendaMobileScrollMinute = displayRange.start + (currentScroll.scrollTop / hourHeight) * 60
            }
            const nextSelectedDate = addDays(state.agendaSelectedDate, safeOffset)
            const nextRenderStart = addDays(startOfDay(nextSelectedDate), -7)
            const nextRenderEnd = addDays(startOfDay(nextSelectedDate), 24)
            const hasBufferedRange = state.agendaLoadedRangeStart &&
              state.agendaLoadedRangeEnd &&
              nextRenderStart >= state.agendaLoadedRangeStart &&
              nextRenderEnd <= state.agendaLoadedRangeEnd
            state.agendaSelectedDate = nextSelectedDate
            state.agendaMonthDate = new Date(state.agendaSelectedDate)
            try {
              if (hasBufferedRange) {
                renderAgenda()
              } else {
                await loadAgenda()
              }
            } finally {
              state.agendaMobilePaging = false
              window.setTimeout(() => {
                state.agendaDidDrag = false
              }, 80)
            }
          }, 210)
        }
        const endPointer = (event) => {
          if (state.agendaMobilePointerId !== event.pointerId) return
          if (state.agendaMobileHorizontalDrag && state.agendaMobileDayWidth) {
            const movedDays = (state.agendaMobileStartTranslate - state.agendaMobileCurrentTranslate) / state.agendaMobileDayWidth
            finishDrag(Math.round(movedDays))
          }
          state.agendaMobilePointerId = null
          state.agendaMobileTouchStartX = null
          state.agendaMobileTouchStartY = null
          state.agendaMobileHorizontalDrag = false
        }
        if (columnsViewport && typeof ResizeObserver !== 'undefined') {
          state.agendaProfessionalResizeObserver = new ResizeObserver(syncMeasurements)
          state.agendaProfessionalResizeObserver.observe(columnsViewport)
        }
        requestAnimationFrame(syncMeasurements)

        for (const surface of els.agendaGridWrap.querySelectorAll('[data-agenda-mobile-gesture]')) {
          surface.addEventListener('pointerdown', (event) => {
            if (event.button !== undefined && event.button !== 0) return
            if (event.target.closest('[data-appointment-id], [data-block-id]')) return
            if (state.agendaMobilePaging) return
            state.agendaMobilePointerId = event.pointerId
            state.agendaMobileTouchStartX = event.clientX
            state.agendaMobileTouchStartY = event.clientY
            state.agendaMobileStartTranslate = state.agendaMobileCurrentTranslate
            state.agendaMobileHorizontalDrag = false
          })

          surface.addEventListener('pointermove', (event) => {
            if (state.agendaMobilePointerId !== event.pointerId || state.agendaMobileTouchStartX === null || state.agendaMobileTouchStartY === null) return
            const deltaX = event.clientX - state.agendaMobileTouchStartX
            const deltaY = event.clientY - state.agendaMobileTouchStartY
            if (!state.agendaMobileHorizontalDrag) {
              if (Math.abs(deltaX) < 10) return
              if (Math.abs(deltaX) <= Math.abs(deltaY) * 1.15) {
                state.agendaMobilePointerId = null
                state.agendaMobileTouchStartX = null
                state.agendaMobileTouchStartY = null
                return
              }
              state.agendaMobileHorizontalDrag = true
              state.agendaDidDrag = true
              surface.setPointerCapture?.(event.pointerId)
            }
            event.preventDefault()
            const minTranslate = -(Math.max(0, dayCount - viewDays)) * state.agendaMobileDayWidth
            const nextTranslate = Math.max(minTranslate, Math.min(0, state.agendaMobileStartTranslate + deltaX))
            applyTransform(nextTranslate)
          })

          surface.addEventListener('pointerup', endPointer)
          surface.addEventListener('pointercancel', endPointer)
        }
      }
    }

    function scrollAgendaMobileToWorkingTime(hourHeight, displayRange) {
      const scroll = els.agendaGridWrap.querySelector('[data-agenda-mobile-scroll]')
      if (!scroll) return
      if (state.agendaMobileScrollMinute !== null) {
        const preservedMinute = Math.max(displayRange.start, Math.min(displayRange.end, state.agendaMobileScrollMinute))
        scroll.scrollTop = ((preservedMinute - displayRange.start) / 60) * hourHeight
        return
      }
      const now = new Date()
      const visibleToday = Array.from({ length: state.agendaViewDays }, (_, index) => index)
        .some((index) => dateKey(addDays(startOfDay(state.agendaSelectedDate), index)) === dateKey(now))
      const preferredMinute = visibleToday ? now.getHours() * 60 + now.getMinutes() - 120 : displayRange.start
      const targetMinute = Math.max(displayRange.start, Math.min(displayRange.end, preferredMinute))
      scroll.scrollTop = ((targetMinute - displayRange.start) / 60) * hourHeight
    }

    function renderAgendaMobileList() {
      const weekStart = startOfWeek(state.agendaSelectedDate)
      const days = Array.from({ length: 7 }, (_, index) => addDays(weekStart, index))
      const appointments = filteredAgendaAppointments()
      const blocks = filteredAgendaBlocks()
      const todayKey = dateKey(new Date())

      els.agendaRange.textContent = formatAgendaRange(days[0], days[6])
      els.agendaToday.textContent = isDateInRange(new Date(), days[0], addDays(days[6], 1)) ? 'Hoy' : 'Ir a hoy'

      const sections = days.map((day) => {
        const key = dateKey(day)
        const dayAppointments = appointments.filter((appointment) => dateKey(new Date(appointment.startAt)) === key)
        const dayBlocks = blocks.filter((block) => dateKey(new Date(block.startAt)) === key)
        const items = dayAppointments.map((appointment) => {
          const start = new Date(appointment.startAt)
          const duration = appointment.totalDurationMinutes || appointment.service?.duration || 30
          const professionalIndex = activeProfessionals().findIndex((item) => item.id === appointment.professionalId)
          const color = agendaProfessionalColor(appointment.professionalId, professionalIndex)
          const noShow = appointment.status === 'NO_SHOW'
          const origin = appointmentOriginMeta(appointment.origin)
          return '<button class="agenda-mobile-item' + (noShow ? ' no-show' : '') + '" type="button" data-appointment-id="' + appointment.id + '" style="--agenda-event-color:' + color + '">' +
            '<span class="agenda-mobile-time">' + escapeHtml(formatTimeOnly(start)) + '<small>' + escapeHtml(formatTimeOnly(addMinutes(start, duration))) + '</small></span>' +
            '<span class="agenda-mobile-copy"><strong>' + escapeHtml(appointmentServiceLabel(appointment)) + '</strong><span>' + escapeHtml((appointment.customer?.name || 'Cliente') + ' · ' + (appointment.professional?.name || 'Profesional')) + '</span></span>' +
            '<span class="agenda-mobile-status">' + appointmentOriginBadgeHtml(origin) + (noShow ? ' Ausente' : '') + '</span>' +
          '</button>'
        })

        for (const block of dayBlocks) {
          const start = new Date(block.startAt)
          const end = new Date(block.endAt)
          items.push('<article class="agenda-mobile-item blocked">' +
            '<span class="agenda-mobile-time">' + escapeHtml(formatTimeOnly(start)) + '<small>' + escapeHtml(formatTimeOnly(end)) + '</small></span>' +
            '<span class="agenda-mobile-copy"><strong>' + escapeHtml(block.title || scheduleBlockReasonLabel(block.reason)) + '</strong><span>' + escapeHtml(block.professional?.name || 'Todos los profesionales') + '</span></span>' +
            '<span class="agenda-mobile-status">Bloqueo</span>' +
          '</article>')
        }

        items.sort((left, right) => {
          const leftTime = left.match(/agenda-mobile-time">([^<]+)/)?.[1] || ''
          const rightTime = right.match(/agenda-mobile-time">([^<]+)/)?.[1] || ''
          return leftTime.localeCompare(rightTime)
        })

        return '<section class="agenda-mobile-day' + (key === todayKey ? ' today' : '') + '">' +
          '<header>' +
            '<button type="button" data-agenda-date="' + key + '">' + escapeHtml(formatAgendaMobileDay(day)) + '</button>' +
            '<span>' + (dayAppointments.length + dayBlocks.length) + '</span>' +
          '</header>' +
          '<div class="agenda-mobile-items">' + (items.length ? items.join('') : '<div class="agenda-mobile-empty">Sin turnos para este dia.</div>') + '</div>' +
          '<button class="agenda-mobile-add" type="button" data-agenda-new-date="' + key + '">Agregar turno</button>' +
        '</section>'
      })

      els.agendaGridWrap.innerHTML = '<div class="agenda-mobile-list">' + sections.join('') + '</div>'

      for (const button of els.agendaGridWrap.querySelectorAll('[data-agenda-date]')) {
        button.addEventListener('click', async () => {
          state.agendaSelectedDate = parseDateKey(button.dataset.agendaDate)
          state.agendaMonthDate = new Date(state.agendaSelectedDate)
          await loadAgenda()
        })
      }

      for (const button of els.agendaGridWrap.querySelectorAll('[data-agenda-new-date]')) {
        button.addEventListener('click', () => {
          openAppointmentDialog({ date: parseDateKey(button.dataset.agendaNewDate) })
        })
      }

      for (const button of els.agendaGridWrap.querySelectorAll('[data-appointment-id]')) {
        button.addEventListener('click', () => {
          const appointment = state.agendaAppointments.find((item) => item.id === button.dataset.appointmentId)
          if (appointment) openAppointmentDialog({ appointment })
        })
      }
    }

    function renderAgendaBlocks(input) {
      const weekStart = startOfWeek(state.agendaSelectedDate)
      const days = Array.from({ length: 7 }, (_, index) => addDays(weekStart, index))
      const blocks = filteredAgendaBlocksForRange(days[0], addDays(days[6], 1))
      const cells = new Map()

      for (const cell of els.agendaGridWrap.querySelectorAll('[data-cell-date][data-cell-minute]')) {
        cells.set(cell.dataset.cellDate + ':' + cell.dataset.cellMinute, cell)
      }

      for (const block of blocks) {
        const blockStart = new Date(block.startAt)
        const blockEnd = new Date(block.endAt)
        for (const day of days) {
          const dayStart = startOfDay(day)
          const dayEnd = addDays(dayStart, 1)
          const segmentStart = new Date(Math.max(blockStart.getTime(), dayStart.getTime()))
          const segmentEnd = new Date(Math.min(blockEnd.getTime(), dayEnd.getTime()))
          if (segmentEnd <= segmentStart) continue

          const segmentStartMinute = segmentStart.getHours() * 60 + segmentStart.getMinutes()
          const segmentEndMinute = dateKey(segmentEnd) !== dateKey(segmentStart)
            ? 24 * 60
            : segmentEnd.getHours() * 60 + segmentEnd.getMinutes()
          const visibleStart = Math.max(input.startMinute, segmentStartMinute)
          const visibleEnd = Math.min(getAgendaDisplayRange().end, segmentEndMinute)
          if (visibleEnd <= visibleStart) continue

          const roundedMinute = visibleStart - (visibleStart % input.step)
          const cell = cells.get(dateKey(day) + ':' + roundedMinute)
          if (!cell) continue

          const top = Math.max(2, (visibleStart - roundedMinute) * input.pixelsPerMinute + 2)
          const height = Math.max(24, (visibleEnd - visibleStart) * input.pixelsPerMinute - 4)
          const title = block.title || scheduleBlockReasonLabel(block.reason)
          const scope = block.professional?.name || 'Todo el salon'
          const blockNode = document.createElement('button')
          blockNode.type = 'button'
          blockNode.className = 'agenda-block'
          blockNode.style.height = height + 'px'
          blockNode.style.top = top + 'px'
          blockNode.dataset.blockId = block.id
          blockNode.title = title + ' - ' + scope
          blockNode.innerHTML = '<strong>' + escapeHtml(title) + '</strong>' +
            '<span>' + escapeHtml(formatTimeOnly(segmentStart) + ' - ' + formatTimeOnly(segmentEnd)) + '</span>' +
            '<span>' + escapeHtml(scope) + '</span>'
          blockNode.addEventListener('click', (event) => {
            event.stopPropagation()
            deleteScheduleBlock(block.id)
          })
          cell.appendChild(blockNode)
        }
      }
    }

    function calculateAgendaDisplayRange(input) {
      const visibleDays = Array.isArray(input.visibleDays) ? input.visibleDays : []
      const businessHours = Array.isArray(input.businessHours) ? input.businessHours : []
      const appointments = Array.isArray(input.appointments) ? input.appointments : []
      const dayKeys = new Set(visibleDays.map((day) => {
        const value = new Date(day)
        return value.getFullYear() + '-' + String(value.getMonth() + 1).padStart(2, '0') + '-' + String(value.getDate()).padStart(2, '0')
      }))
      const dayOfWeeks = new Set(visibleDays.map((day) => new Date(day).getDay()))
      const visibleBusinessHours = businessHours.filter((hour) => dayOfWeeks.has(Number(hour.dayOfWeek)))
      const relevantBusinessHours = visibleBusinessHours.length ? visibleBusinessHours : businessHours
      const parseTime = (value) => {
        const parts = String(value || '').split(':').map(Number)
        return Number.isFinite(parts[0]) && Number.isFinite(parts[1]) ? parts[0] * 60 + parts[1] : null
      }
      const starts = relevantBusinessHours.map((hour) => parseTime(hour.startTime)).filter((minute) => minute !== null)
      const ends = relevantBusinessHours.map((hour) => parseTime(hour.endTime)).filter((minute) => minute !== null)
      const configuredStart = starts.length ? Math.min(...starts) : 9 * 60
      const configuredEnd = ends.length ? Math.max(...ends) : 19 * 60
      let start = Math.max(0, Math.floor((configuredStart - 60) / 60) * 60)
      let end = Math.min(24 * 60, Math.ceil((configuredEnd + 60) / 60) * 60)

      for (const appointment of appointments) {
        if (appointment.status === 'CANCELLED') continue
        const appointmentStart = new Date(appointment.startAt)
        if (Number.isNaN(appointmentStart.getTime())) continue
        const appointmentKey = appointmentStart.getFullYear() + '-' + String(appointmentStart.getMonth() + 1).padStart(2, '0') + '-' + String(appointmentStart.getDate()).padStart(2, '0')
        if (!dayKeys.has(appointmentKey)) continue
        const rawDuration = Number(appointment.totalDurationMinutes || appointment.service?.duration || 30)
        const duration = Number.isFinite(rawDuration) && rawDuration > 0 ? rawDuration : 30
        const appointmentStartMinute = appointmentStart.getHours() * 60 + appointmentStart.getMinutes()
        const appointmentEndMinute = Math.min(24 * 60, appointmentStartMinute + Math.max(1, duration))
        start = Math.min(start, Math.floor(appointmentStartMinute / 60) * 60)
        end = Math.max(end, Math.ceil(appointmentEndMinute / 60) * 60)
      }

      return {
        start: Math.max(0, Math.min(24 * 60, start)),
        end: Math.max(0, Math.min(24 * 60, end))
      }
    }

    function getAgendaDisplayRange(visibleDays) {
      const days = Array.isArray(visibleDays) && visibleDays.length
        ? visibleDays
        : [startOfDay(state.agendaSelectedDate)]
      const rangeStart = startOfDay(days[0])
      const rangeEnd = addDays(startOfDay(days[days.length - 1]), 1)
      return calculateAgendaDisplayRange({
        visibleDays: days,
        businessHours: state.businessHours,
        appointments: filteredAgendaAppointmentsForRange(rangeStart, rangeEnd)
      })
    }

    function renderAgendaEvents(input) {
      const appointments = filteredAgendaAppointments()
      const layout = buildAgendaEventLayout(appointments)
      const cells = new Map()
      for (const cell of els.agendaGridWrap.querySelectorAll('[data-cell-date][data-cell-minute]')) {
        cells.set(cell.dataset.cellDate + ':' + cell.dataset.cellMinute, cell)
      }

      for (const appointment of appointments) {
        const start = new Date(appointment.startAt)
        const minute = start.getHours() * 60 + start.getMinutes()
        const roundedMinute = minute - (minute % input.step)
        const cell = cells.get(dateKey(start) + ':' + roundedMinute)
        if (!cell) continue

        const duration = appointment.totalDurationMinutes || appointment.service?.duration || input.step
        const height = Math.max(24, duration * input.pixelsPerMinute - 4)
        const top = Math.max(2, (minute - roundedMinute) * input.pixelsPerMinute + 2)
        const customer = appointment.customer?.name || 'Cliente'
        const professional = appointment.professional?.name || 'Profesional'
        const service = appointmentServiceLabel(appointment)
        const professionalIndex = activeProfessionals().findIndex((item) => item.id === appointment.professionalId)
        const eventColor = agendaProfessionalColor(appointment.professionalId, professionalIndex)
        const placement = layout.get(appointment.id) || { column: 0, columns: 1 }
        const gap = 3
        const leftOffset = 5 + (gap / 2)
        const widthOffset = gap + (10 / placement.columns)
        const noShow = appointment.status === 'NO_SHOW'
        const pending = state.agendaPendingAppointmentIds.has(appointment.id)
        const depositIndicator = agendaDepositIndicator(appointment)
        const origin = appointmentOriginMeta(appointment.origin)

        const event = document.createElement('article')
        event.className = 'agenda-event' + (depositIndicator ? ' has-deposit' : '') + (placement.columns > 1 ? ' is-overlap' : '') + (noShow ? ' no-show' : '') + (pending ? ' is-pending' : '')
        event.style.height = height + 'px'
        event.style.top = top + 'px'
        event.style.left = 'calc(' + ((placement.column * 100) / placement.columns) + '% + ' + leftOffset + 'px)'
        event.style.right = 'auto'
        event.style.width = 'calc(' + (100 / placement.columns) + '% - ' + widthOffset + 'px)'
        event.style.setProperty('--agenda-event-color', eventColor)
        if (depositIndicator) event.style.setProperty('--agenda-deposit-color', depositIndicator.color)
        event.title = customer + ' - ' + service + ' con ' + professional + ' - ' + origin.label + (depositIndicator ? ' - ' + depositIndicator.label : '') + (noShow ? ' - Ausente' : '') + (pending ? ' - Guardando cambio' : '')
        event.innerHTML = '<strong>' + escapeHtml(service) + '</strong>' +
          '<span>' + appointmentOriginBadgeHtml(origin) + ' ' + escapeHtml(customer + (noShow ? ' - Ausente' : '')) + '</span>' +
          '<span>' + escapeHtml(professional) + '</span>'
        event.dataset.appointmentId = appointment.id
        event.draggable = false
        event.addEventListener('click', (clickEvent) => {
          clickEvent.stopPropagation()
          if (state.agendaDidDrag) {
            state.agendaDidDrag = false
            return
          }
          openAppointmentDialog({ appointment })
        })
        event.addEventListener('pointerdown', (pointerEvent) => {
          startAgendaPointerDrag(pointerEvent, event, appointment.id)
        })
        cell.appendChild(event)
      }
    }

    function enableAgendaDragAndDrop() {
      clearAgendaPointerDrag()
    }

    function startAgendaPointerDrag(pointerEvent, eventNode, appointmentId) {
      if (pointerEvent.button !== 0) return
      if (!canEditAppointments()) {
        showCrmToast('No tenes permiso para editar turnos.', 'error')
        return
      }
      if (state.agendaPendingAppointmentIds.has(appointmentId)) return

      clearAgendaPointerDrag()

      const rect = eventNode.getBoundingClientRect()
      state.agendaPointerDrag = {
        appointmentId,
        pointerId: pointerEvent.pointerId,
        eventNode,
        ghost: null,
        startX: pointerEvent.clientX,
        startY: pointerEvent.clientY,
        offsetX: pointerEvent.clientX - rect.left,
        offsetY: pointerEvent.clientY - rect.top,
        width: rect.width,
        height: rect.height,
        targetCell: null,
        dragging: false
      }

      try {
        eventNode.setPointerCapture?.(pointerEvent.pointerId)
      } catch {}
      window.addEventListener('pointermove', handleAgendaPointerMove, true)
      window.addEventListener('pointerup', handleAgendaPointerEnd, true)
      window.addEventListener('pointercancel', handleAgendaPointerCancel, true)
      window.addEventListener('blur', handleAgendaPointerCancel)
      document.addEventListener('visibilitychange', handleAgendaVisibilityChange)
    }

    function handleAgendaPointerMove(pointerEvent) {
      const drag = state.agendaPointerDrag
      if (!drag || pointerEvent.pointerId !== drag.pointerId) return

      const moved = Math.hypot(pointerEvent.clientX - drag.startX, pointerEvent.clientY - drag.startY)
      if (!drag.dragging && moved < 5) return
      pointerEvent.preventDefault()

      if (!drag.dragging) {
        drag.dragging = true
        state.agendaDraggingAppointmentId = drag.appointmentId
        state.agendaDidDrag = true
        drag.eventNode.classList.add('dragging')
        drag.ghost = createAgendaDragGhost(drag)
        document.body.appendChild(drag.ghost)
      }

      moveAgendaDragGhost(drag, pointerEvent.clientX, pointerEvent.clientY)
      updateAgendaPointerTarget(drag, pointerEvent.clientX, pointerEvent.clientY)
    }

    function handleAgendaPointerEnd(pointerEvent) {
      const drag = state.agendaPointerDrag
      if (!drag || pointerEvent.pointerId !== drag.pointerId) return

      if (!drag.dragging) {
        clearAgendaPointerDrag()
        return
      }

      pointerEvent.preventDefault()
      const targetCell = drag.targetCell
      const appointmentId = drag.appointmentId
      clearAgendaPointerDrag({ keepDidDrag: true })

      if (!targetCell) {
        showCrmToast('Solta el turno sobre un horario disponible.', 'error')
        return
      }

      moveAgendaAppointment(
        appointmentId,
        targetCell.dataset.cellDate,
        Number(targetCell.dataset.cellMinute),
        targetCell.dataset.cellProfessionalId || undefined
      ).catch((error) => showCrmToast(error.message, 'error'))
    }

    function handleAgendaPointerCancel(pointerEvent) {
      const drag = state.agendaPointerDrag
      if (!drag) {
        removeOrphanAgendaDragGhosts()
        return
      }
      if (pointerEvent?.pointerId !== undefined && pointerEvent.pointerId !== drag.pointerId) return
      clearAgendaPointerDrag()
    }

    function handleAgendaVisibilityChange() {
      if (document.hidden) handleAgendaPointerCancel()
    }

    function createAgendaDragGhost(drag) {
      const ghost = drag.eventNode.cloneNode(true)
      ghost.classList.remove('dragging', 'is-pending')
      ghost.classList.add('agenda-drag-ghost')
      ghost.querySelector('[data-agenda-new-at]')?.remove()
      ghost.style.width = drag.width + 'px'
      ghost.style.height = drag.height + 'px'
      ghost.removeAttribute('data-appointment-id')
      return ghost
    }

    function moveAgendaDragGhost(drag, clientX, clientY) {
      if (!drag.ghost) return
      drag.ghost.style.left = (clientX - drag.offsetX) + 'px'
      drag.ghost.style.top = (clientY - drag.offsetY) + 'px'
    }

    function updateAgendaPointerTarget(drag, clientX, clientY) {
      const cell = document.elementsFromPoint(clientX, clientY)
        .map((element) => element.closest?.('[data-cell-date][data-cell-minute]'))
        .find(Boolean)
      for (const current of els.agendaGridWrap.querySelectorAll('.drag-target, .drag-warning, .drag-invalid')) {
        if (current !== cell) current.classList.remove('drag-target', 'drag-warning', 'drag-invalid')
      }

      if (!cell || !els.agendaGridWrap.contains(cell)) {
        drag.targetCell = null
        clearAgendaDropPreview()
        return
      }

      const appointment = state.agendaAppointments.find((item) => item.id === drag.appointmentId)
      if (!appointment) return
      const targetProfessionalId = cell.dataset.cellProfessionalId || appointment.professionalId
      const targetProfessional = state.professionals.find((item) => item.id === targetProfessionalId)
      const serviceIds = appointmentServiceIds(appointment)
      const assignedServiceIds = new Set((targetProfessional?.services || []).map((service) => service.id))
      const serviceMismatch = Boolean(targetProfessional && serviceIds.some((serviceId) => !assignedServiceIds.has(serviceId)))
      const warningTarget = cell.classList.contains('closed') || serviceMismatch
      cell.classList.add('drag-target')
      cell.classList.toggle('drag-warning', warningTarget && !serviceMismatch)
      cell.classList.toggle('drag-invalid', serviceMismatch)

      drag.targetCell = cell
      renderAgendaDropPreview(
        drag.appointmentId,
        cell,
        cell.dataset.cellDate,
        Number(cell.dataset.cellMinute),
        targetProfessionalId
      )
    }

    function clearAgendaPointerDrag(options = {}) {
      const drag = state.agendaPointerDrag
      window.removeEventListener('pointermove', handleAgendaPointerMove, true)
      window.removeEventListener('pointerup', handleAgendaPointerEnd, true)
      window.removeEventListener('pointercancel', handleAgendaPointerCancel, true)
      window.removeEventListener('blur', handleAgendaPointerCancel)
      document.removeEventListener('visibilitychange', handleAgendaVisibilityChange)
      drag?.eventNode.classList.remove('dragging')
      drag?.ghost?.remove()
      removeOrphanAgendaDragGhosts()
      state.agendaPointerDrag = null
      state.agendaDraggingAppointmentId = null
      clearAgendaDragTargets()
      if (options.keepDidDrag) {
        setTimeout(() => {
          state.agendaDidDrag = false
        }, 200)
      } else {
        state.agendaDidDrag = false
      }
    }

    function removeOrphanAgendaDragGhosts() {
      document.querySelectorAll('.agenda-drag-ghost').forEach((ghost) => ghost.remove())
    }

    function clearAgendaDragTargets() {
      for (const cell of els.agendaGridWrap.querySelectorAll('.drag-target, .drag-warning, .drag-invalid')) {
        cell.classList.remove('drag-target', 'drag-warning', 'drag-invalid')
      }
      clearAgendaDropPreview()
    }

    function clearAgendaDropPreview() {
      state.agendaDragPreviewKey = null
      els.agendaGridWrap.querySelector('.agenda-drop-preview')?.remove()
    }

    function renderAgendaDropPreview(appointmentId, cell, targetDateKey, targetMinute, targetProfessionalId) {
      const appointment = state.agendaAppointments.find((item) => item.id === appointmentId)
      if (!appointment) return

      const previewKey = appointmentId + ':' + targetDateKey + ':' + targetMinute + ':' + targetProfessionalId
      if (state.agendaDragPreviewKey === previewKey && cell.querySelector('.agenda-drop-preview')) return

      clearAgendaDropPreview()
      state.agendaDragPreviewKey = previewKey

      const target = parseDateKey(targetDateKey)
      target.setHours(Math.floor(targetMinute / 60), targetMinute % 60, 0, 0)
      const duration = appointment.totalDurationMinutes || appointment.service?.duration || Number(els.agendaStep.value || 30)
      const displayRange = getAgendaDisplayRange()
      const pixelsPerMinute = els.agendaGridWrap.querySelector('.agenda-gcal-frame') ? 88 / 60 : 28 / 15
      const height = Math.max(24, duration * pixelsPerMinute - 4)
      const customer = appointment.customer?.name || 'Cliente'
      const service = appointmentServiceLabel(appointment)
      const resolvedProfessionalId = targetProfessionalId || appointment.professionalId
      const targetProfessional = state.professionals.find((item) => item.id === resolvedProfessionalId)
      const professionalIndex = activeProfessionals().findIndex((item) => item.id === resolvedProfessionalId)
      const eventColor = agendaProfessionalColor(resolvedProfessionalId, professionalIndex)

      const preview = document.createElement('article')
      preview.className = 'agenda-drop-preview'
      preview.style.height = height + 'px'
      preview.style.setProperty('--agenda-event-color', eventColor)
      preview.innerHTML = '<strong>' + escapeHtml(service) + '</strong>' +
        '<span>' + escapeHtml(customer + (targetProfessional ? ' · ' + targetProfessional.name : '')) + '</span>' +
        '<span>' + escapeHtml(formatTimeOnly(target) + ' - ' + formatTimeOnly(addMinutes(target, duration))) + '</span>'
      if (targetMinute < displayRange.start || targetMinute >= displayRange.end) return
      cell.appendChild(preview)
    }

    async function moveAgendaAppointment(appointmentId, targetDateKey, targetMinute, requestedProfessionalId) {
      const appointment = state.agendaAppointments.find((item) => item.id === appointmentId)
      if (!appointment) return
      if (state.agendaPendingAppointmentIds.has(appointmentId)) return

      const target = parseDateKey(targetDateKey)
      target.setHours(Math.floor(targetMinute / 60), targetMinute % 60, 0, 0)
      const targetProfessionalId = requestedProfessionalId || appointment.professionalId
      if (
        new Date(appointment.startAt).getTime() === target.getTime() &&
        appointment.professionalId === targetProfessionalId
      ) return

      const targetProfessional = state.professionals.find((item) => item.id === targetProfessionalId)
      const serviceIds = appointmentServiceIds(appointment)
      const payload = {
        customerId: appointment.customerId,
        professionalId: targetProfessionalId,
        serviceId: appointment.serviceId,
        serviceIds,
        startAt: target.toISOString()
      }
      state.agendaPendingAppointmentIds.add(appointmentId)
      renderAgenda()

      try {
        let saved
        try {
          saved = await getJson('/appointments/' + appointmentId, {
            method: 'PATCH',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(payload)
          })
        } catch (error) {
          const conflicts = Array.isArray(error.body?.conflicts) ? error.body.conflicts : []
          if (error.body?.code !== 'APPOINTMENT_AVAILABILITY_CONFLICT' || error.body?.forceable !== true || !conflicts.length) {
            throw error
          }

          const conflictList = conflicts.map((conflict) => '• ' + conflict.message).join('\\n')
          if (!canForceAppointmentOverrides()) {
            throw new Error(conflictList + '\\nNo tenés permiso para crear excepciones o sobreturnos.')
          }

          const targetDescription = (targetProfessional?.name || 'el profesional seleccionado') +
            ' el ' + formatDateTime(target)
          const wantsOverride = await requestCrmConfirmation(
            'El turno no puede moverse normalmente a ' + targetDescription + ':\\n\\n' + conflictList +
            '\\n\\n¿Querés continuar y evaluar una excepción?',
            {
              title: 'El cambio tiene conflictos',
              confirmLabel: 'Continuar',
              danger: false
            }
          )
          if (!wantsOverride) return

          const confirmedOverride = await requestCrmConfirmation(
            'Esta es la confirmación final. El turno se guardará aunque exista una superposición, un bloqueo o el profesional no esté trabajando.\\n\\n' + conflictList,
            {
              title: 'Confirmar sobreturno o excepción',
              confirmLabel: 'Sí, mover como excepción'
            }
          )
          if (!confirmedOverride) return

          saved = await getJson('/appointments/' + appointmentId, {
            method: 'PATCH',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ ...payload, force: true })
          })
        }

        state.agendaAppointments = state.agendaAppointments.map((item) => {
          return item.id === appointmentId ? { ...item, ...saved } : item
        })
        state.agendaSelectedDate = target
        state.agendaMonthDate = new Date(target)
        showCrmToast('Turno movido a ' + (targetProfessional?.name || 'la nueva agenda') + '.', 'success')
      } catch (error) {
        showCrmToast(error.message, 'error')
      } finally {
        state.agendaPendingAppointmentIds.delete(appointmentId)
        state.agendaDraggingAppointmentId = null
        renderAgenda()
      }
    }

    function buildAgendaEventLayout(appointments) {
      const byDay = new Map()
      for (const appointment of appointments) {
        const start = new Date(appointment.startAt)
        const startMinute = start.getHours() * 60 + start.getMinutes()
        const duration = appointment.totalDurationMinutes || appointment.service?.duration || Number(els.agendaStep.value || 30)
        const item = {
          id: appointment.id,
          start: startMinute,
          end: startMinute + duration,
          column: 0
        }
        const key = dateKey(start)
        byDay.set(key, (byDay.get(key) || []).concat(item))
      }

      const layout = new Map()
      for (const items of byDay.values()) {
        const sorted = items.sort((left, right) => left.start - right.start || left.end - right.end)
        let cluster = []
        let clusterEnd = 0

        for (const item of sorted) {
          if (cluster.length && item.start >= clusterEnd) {
            assignAgendaClusterLayout(cluster, layout)
            cluster = []
          }

          cluster.push(item)
          clusterEnd = Math.max(clusterEnd, item.end)
        }

        if (cluster.length) {
          assignAgendaClusterLayout(cluster, layout)
        }
      }

      return layout
    }

    function assignAgendaClusterLayout(cluster, layout) {
      const columns = []
      for (const item of cluster) {
        let column = columns.findIndex((end) => end <= item.start)
        if (column === -1) {
          column = columns.length
          columns.push(item.end)
        } else {
          columns[column] = item.end
        }
        item.column = column
      }

      const columnCount = Math.max(1, columns.length)
      for (const item of cluster) {
        layout.set(item.id, {
          column: item.column,
          columns: columnCount
        })
      }
    }

    function filteredAgendaAppointments() {
      const weekStart = startOfWeek(state.agendaSelectedDate)
      const weekEnd = addDays(weekStart, 7)
      return filteredAgendaAppointmentsForRange(weekStart, weekEnd)
    }

    function filteredAgendaAppointmentsForRange(from, to) {
      const professionalId = els.agendaProfessional?.value || ''
      const serviceId = els.agendaService?.value || ''

      return state.agendaAppointments
        .filter((appointment) => appointment.status !== 'CANCELLED')
        .filter((appointment) => {
          const start = new Date(appointment.startAt)
          return start >= from && start < to
        })
        .filter((appointment) => !professionalId || appointment.professionalId === professionalId)
        .filter((appointment) =>
          !serviceId ||
          appointment.serviceId === serviceId ||
          (appointment.serviceItems || []).some((item) => item.serviceId === serviceId)
        )
        .sort((left, right) => new Date(left.startAt).getTime() - new Date(right.startAt).getTime())
    }

    function filteredAgendaBlocks() {
      const weekStart = startOfWeek(state.agendaSelectedDate)
      const weekEnd = addDays(weekStart, 7)
      return filteredAgendaBlocksForRange(weekStart, weekEnd)
    }

    function filteredAgendaBlocksForRange(from, to) {
      const professionalId = els.agendaProfessional?.value || ''

      return state.agendaBlocks
        .filter((block) => {
          const start = new Date(block.startAt)
          const end = new Date(block.endAt)
          return end > from && start < to
        })
        .filter((block) => !professionalId || !block.professionalId || block.professionalId === professionalId)
        .sort((left, right) => new Date(left.startAt).getTime() - new Date(right.startAt).getTime())
    }

    function scheduleBlockReasonLabel(reason) {
      const labels = {
        ABSENCE: 'Falta',
        VACATION: 'Vacaciones',
        LATE_ARRIVAL: 'Llegada tarde',
        SICK_LEAVE: 'Enfermedad',
        PERSONAL: 'Personal',
        TRAINING: 'Capacitacion',
        MAINTENANCE: 'Mantenimiento',
        HOLIDAY: 'Feriado',
        OTHER: 'Bloqueo'
      }
      return labels[reason] || 'Bloqueo'
    }

    function isClosedAgendaSlot(day, minute) {
      const professionalId = els.agendaProfessional?.value || ''
      const professionals = professionalId
        ? state.professionals.filter((professional) => professional.id === professionalId)
        : activeProfessionals()

      if (professionals.length === 0) {
        return false
      }

      return !professionals.some((professional) => professionalWorksAt(professional, day, minute))
    }

    function isClosedAgendaSlotForProfessional(day, minute, professionalId) {
      const professional = state.professionals.find((item) => item.id === professionalId)
      return professional ? !professionalWorksAt(professional, day, minute) : false
    }

    function professionalWorksAt(professional, day, minute) {
      return (professional.workingHours || []).some((hour) => {
        return hour.dayOfWeek === day.getDay() &&
          minute >= timeToMinutes(hour.startTime) &&
          minute < timeToMinutes(hour.endTime)
      })
    }

    function syncAppointmentDepositFields() {
      const paid = els.appointmentDepositPaid.checked
      els.appointmentDepositAmountRow.hidden = !paid
      els.appointmentDepositAmount.disabled = !paid
      if (!paid) els.appointmentDepositAmount.value = ''
    }

    function openAppointmentDialog(input = {}) {
      renderAppointmentFormOptions()
      els.appointmentFeedback.textContent = ''
      const appointment = input.appointment
      state.editingAppointmentId = appointment?.id || null
      els.appointmentTitle.textContent = appointment ? 'Editar turno' : 'Nuevo turno'
      els.appointmentSubmit.textContent = appointment ? 'Guardar cambios' : 'Cargar turno'
      els.appointmentDelete.hidden = !appointment
      els.appointmentNoShow.hidden = !appointment || appointment.status === 'CANCELLED'

      if (appointment) {
        if (appointment.customer && !state.customers.some((customer) => customer.id === appointment.customerId)) {
          state.customers.push({ ...appointment.customer, id: appointment.customerId })
        }
        els.appointmentStart.value = toDatetimeLocalValue(new Date(appointment.startAt))
        els.appointmentProfessional.value = appointment.professionalId || ''
        const compatibleServices = renderAppointmentServiceOptions(appointment.serviceId || '')
        if (!compatibleServices.some((service) => service.id === appointment.serviceId)) {
          els.appointmentFeedback.textContent = 'El servicio del turno ya no está asignado a este profesional. Selecciona uno compatible.'
          els.appointmentService.value = ''
        }
        els.appointmentCustomer.value = appointment.customerId || ''
        els.appointmentCustomerName.value = appointment.customer?.name || ''
        els.appointmentCustomerPhone.value = appointment.customer?.phone || ''
        els.appointmentNotes.value = appointment.notes || ''
        els.appointmentDepositPaid.checked = appointment.manualDepositPaid === true
        els.appointmentDepositAmount.value = appointment.manualDepositAmount || ''
        const origin = appointmentOriginMeta(appointment.origin)
        els.appointmentOriginRow.hidden = false
        els.appointmentOriginBadge.className = 'appointment-origin-badge ' + origin.className
        els.appointmentOriginBadge.textContent = origin.code
        els.appointmentOriginLabel.textContent = origin.label
        els.appointmentNoShow.textContent = appointment.status === 'NO_SHOW' ? 'Quitar ausente' : 'Marcar ausente'
        els.appointmentNoShow.className = appointment.status === 'NO_SHOW' ? 'secondary' : 'danger'
        els.appointmentFeedback.textContent = appointment.status === 'NO_SHOW' ? 'Este turno esta marcado como ausente.' : ''
      } else {
        const date = input.date || state.agendaSelectedDate || new Date()
        const minute = Number.isFinite(input.minute) ? input.minute : 9 * 60
        els.appointmentStart.value = toDatetimeLocalValue(addMinutes(startOfDay(date), minute))

        const selectedProfessionalId = input.professionalId || els.agendaProfessional.value
        const selectedServiceId = input.serviceId || els.agendaService.value
        els.appointmentProfessional.value = selectedProfessionalId || activeProfessionals()[0]?.id || ''
        const compatibleServices = renderAppointmentServiceOptions(selectedServiceId)
        if (compatibleServices.length === 0) {
          els.appointmentFeedback.textContent = 'Este profesional no tiene servicios asignados.'
        } else if (input.additionalAtOccupiedTime) {
          els.appointmentFeedback.textContent = 'Nuevo turno en un horario ocupado: podes elegir otro profesional o habilitar el sobreturno.'
        }
        els.appointmentCustomer.value = ''
        els.appointmentCustomerSearch.value = ''
        els.appointmentCustomerName.value = ''
        els.appointmentCustomerPhone.value = ''
        els.appointmentNotes.value = ''
        els.appointmentDepositPaid.checked = false
        els.appointmentDepositAmount.value = ''
        els.appointmentOriginRow.hidden = true
      }

      els.appointmentAdditional.open = Boolean(
        appointment && (els.appointmentNotes.value.trim() || els.appointmentDepositPaid.checked)
      )
      syncAppointmentDepositFields()
      syncAppointmentCustomerFields()
      const protectsScheduledCustomer = Boolean(appointment && !canViewAppointmentCustomerData())
      const customerSearchRow = els.appointmentCustomerSearch.closest('.form-row')
      const customerPhoneRow = els.appointmentCustomerPhone.closest('.form-row')
      if (customerSearchRow) customerSearchRow.hidden = protectsScheduledCustomer
      if (customerPhoneRow) customerPhoneRow.hidden = protectsScheduledCustomer
      els.appointmentCustomerName.readOnly = protectsScheduledCustomer
      if (protectsScheduledCustomer) els.appointmentCustomerPhone.value = ''
      updateAppointmentContactActions(appointment)
      applyAgendaPermissions()
      els.appointmentDialog.hidden = false
      els.appointmentStart.focus()
    }

    function closeAppointmentDialog() {
      els.appointmentDialog.hidden = true
      els.appointmentFeedback.textContent = ''
      state.editingAppointmentId = null
      els.appointmentDelete.hidden = true
      els.appointmentNoShow.hidden = true
      closeAppointmentCustomerResults()
      updateAppointmentContactActions(null)
    }

    function editingAgendaAppointment() {
      return state.agendaAppointments.find((item) => item.id === state.editingAppointmentId) || null
    }

    function syncAppointmentCustomerFields() {
      const customer = state.customers.find((item) => item.id === els.appointmentCustomer.value)
      if (customer) {
        els.appointmentCustomerSearch.value = appointmentCustomerLabel(customer)
        els.appointmentCustomerName.value = customer.name
        els.appointmentCustomerPhone.value = customer.phone
      } else if (!els.appointmentCustomer.value) {
        els.appointmentCustomerName.value = ''
        els.appointmentCustomerPhone.value = ''
      }
      updateAppointmentContactActions(editingAgendaAppointment())
    }

    function updateAppointmentContactActions(appointment) {
      const phone = els.appointmentCustomerPhone.value || appointment?.customer?.phone || ''
      const digits = normalizePhone(phone)
      const hasContact = Boolean(state.editingAppointmentId && digits && canViewAppointmentCustomerData())
      const canOpenChat = hasContact && canOpenAppointmentConversations()
      const canUseWhatsapp = hasContact && canMessageAppointmentCustomer()
      const reminderAppointment = appointment
        ? {
            ...appointment,
            startAt: els.appointmentStart.value || appointment.startAt,
            customer: {
              ...(appointment.customer || {}),
              name: els.appointmentCustomerName.value || appointment.customer?.name,
              phone
            },
            service: state.services.find((item) => item.id === els.appointmentService.value) || appointment.service
          }
        : null
      const reminderMessage = reminderAppointment
        ? buildAppointmentReminderMessage(reminderAppointment, els.appointmentCustomerName.value || 'cliente')
        : ''

      els.appointmentContactActions.hidden = !canOpenChat && !canUseWhatsapp
      els.appointmentWhatsapp.hidden = !canUseWhatsapp
      els.appointmentWhatsapp.href = canUseWhatsapp
        ? whatsappAppUrl(digits, reminderMessage)
        : '#'
      els.appointmentOpenChat.hidden = !canOpenChat
      els.appointmentOpenChat.disabled = !canOpenChat
      els.appointmentOpenChat.dataset.phone = canOpenChat ? phone : ''
      els.appointmentOpenChat.dataset.reminderMessage = canOpenChat ? reminderMessage : ''
    }

    function openAppointmentWhatsapp(event) {
      event.preventDefault()
      if (!els.appointmentWhatsapp.href || els.appointmentWhatsapp.href.endsWith('#')) return
      window.location.href = els.appointmentWhatsapp.href
      showCrmToast('Abriendo WhatsApp Desktop con el recordatorio precargado. Si no se abre, revisa que WhatsApp Desktop este instalado.', 'success')
    }

    async function openAppointmentCustomerChat() {
      const phone = els.appointmentOpenChat.dataset.phone || els.appointmentCustomerPhone.value
      const normalized = normalizePhone(phone)
      if (!normalized) {
        els.appointmentFeedback.textContent = 'Este turno no tiene telefono cargado.'
        return
      }

      let conversation = state.conversations.find((item) => normalizePhone(item.phone) === normalized)
      if (!conversation) {
        const phonesToTry = Array.from(new Set([phone, normalized].filter(Boolean)))
        const conversations = []
        for (const phoneToTry of phonesToTry) {
          const params = new URLSearchParams({
            phone: phoneToTry,
            take: '1',
            archive: 'all'
          })
          if (state.businessId) params.set('businessId', state.businessId)
          conversations.push(...await getJson('/crm/conversations?' + params.toString()))
          if (conversations.some((item) => normalizePhone(item.phone) === normalized)) break
        }
        conversation = conversations.find((item) => normalizePhone(item.phone) === normalized) || conversations[0]
      }

      if (!conversation) {
        els.appointmentFeedback.textContent = 'No encontre un chat para este cliente todavia.'
        return
      }

      if (!state.conversations.some((item) => item.id === conversation.id)) {
        state.conversations.unshift(conversation)
      }
      const reminderMessage = els.appointmentOpenChat.dataset.reminderMessage || buildAppointmentReminderMessage(editingAgendaAppointment(), conversationDisplayName(conversation))
      closeAppointmentDialog()
      setSection('conversations')
      await selectConversation(conversation.id)
      if (whatsappReplyWindowState().canReply) {
        els.replyText.value = reminderMessage
        els.replyText.focus()
      } else {
        updateComposerAvailability()
        showCrmToast('El chat interno no permite responder porque pasaron mas de 24 hs desde el ultimo mensaje del cliente.', 'error')
      }
    }

    async function confirmManualAppointmentOverride(conflicts, input) {
      const conflictList = conflicts.map((conflict) => '• ' + conflict.message).join('\\n')
      if (!canForceAppointmentOverrides()) {
        els.appointmentFeedback.textContent = conflictList + '\\nNo tenés permiso para crear excepciones o sobreturnos.'
        return false
      }
      const start = new Date(input.startAt)
      const professional = state.professionals.find((item) => item.id === input.professionalId)?.name || 'Profesional'
      const service = state.services.find((item) => item.id === input.serviceId)
      const duration = service?.duration || 30
      return requestCrmConfirmation(
        'Este turno necesita una excepción:\\n\\n' + conflictList + '\\n\\n' +
        'Profesional: ' + professional + '\\n' +
        'Servicio: ' + (service?.name || 'Servicio') + '\\n' +
        'Horario: ' + formatDateTime(start) + ' a ' + formatTimeOnly(addMinutes(start, duration)) + '\\n\\n' +
        '¿Querés crearlo igualmente?',
        {
          title: 'Confirmar turno excepcional',
          confirmLabel: 'Crear como excepción',
          danger: false
        }
      )
    }

    async function saveManualAppointment(event) {
      event.preventDefault()
      els.appointmentFeedback.textContent = ''

      if (state.editingAppointmentId ? !canEditAppointments() : !canCreateAppointments()) {
        els.appointmentFeedback.textContent = state.editingAppointmentId
          ? 'No tenes permiso para editar turnos.'
          : 'No tenes permiso para cargar turnos.'
        return
      }

      const startAt = els.appointmentStart.value
      const professionalId = els.appointmentProfessional.value
      const serviceId = els.appointmentService.value
      let force = false
      const manualDepositPaid = els.appointmentDepositPaid.checked
      const manualDepositAmountText = els.appointmentDepositAmount.value.trim()
      const manualDepositAmount = manualDepositAmountText ? Number(manualDepositAmountText) : null
      const notes = els.appointmentNotes.value.trim()
      let customerId = els.appointmentCustomer.value

      if (!startAt || !professionalId || !serviceId) {
        els.appointmentFeedback.textContent = 'Completa fecha, profesional y servicio.'
        return
      }

      if (!appointmentServicesForProfessional(professionalId).some((service) => service.id === serviceId)) {
        els.appointmentFeedback.textContent = 'El profesional seleccionado no realiza ese servicio.'
        return
      }

      if (
        manualDepositPaid &&
        manualDepositAmount !== null &&
        (!Number.isInteger(manualDepositAmount) || manualDepositAmount <= 0)
      ) {
        els.appointmentFeedback.textContent = 'El monto de la seña debe ser un número entero mayor a 0.'
        els.appointmentDepositAmount.focus()
        return
      }

      let availability
      try {
        availability = await getJson('/appointments/check-availability', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            professionalId,
            serviceId,
            startAt: new Date(startAt).toISOString(),
            ...(state.editingAppointmentId ? { appointmentId: state.editingAppointmentId } : {})
          })
        })
      } catch (error) {
        els.appointmentFeedback.textContent = error.message
        return
      }

      const conflicts = Array.isArray(availability.conflicts) ? availability.conflicts : []
      if (conflicts.length) {
        const confirmedOverride = await confirmManualAppointmentOverride(conflicts, { startAt, professionalId, serviceId })
        if (!confirmedOverride) return
        force = true
      }

      if (!setButtonLoading(
        els.appointmentSubmit,
        true,
        state.editingAppointmentId ? 'Guardando...' : 'Creando turno...'
      )) return
      try {
        if (!customerId) {
          const name = els.appointmentCustomerName.value.trim()
          const phone = els.appointmentCustomerPhone.value.trim()
          if (!name) {
            els.appointmentFeedback.textContent = 'Elegi un cliente o carga su nombre.'
            return
          }

          const customer = await getJson('/customers', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ name, phone, businessId: state.businessId })
          })
          if (customer.wasExisting) {
            showCrmToast('Ese teléfono ya pertenece a ' + customer.name + '. El turno se cargará en su ficha existente.', 'success')
          } else if (customer.isProvisional) {
            showCrmToast('Turno presencial cargado sin teléfono. Podés completar el contacto más adelante.', 'success')
          }
          customerId = customer.id
          state.customers = await getJson(businessScopedPath('/customers'))
          renderAppointmentFormOptions()
        } else {
          const selectedCustomer = state.customers.find((customer) => customer.id === customerId)
          const name = els.appointmentCustomerName.value.trim()
          const phone = els.appointmentCustomerPhone.value.trim()
          if (selectedCustomer && phone && (phone !== selectedCustomer.phone || name !== selectedCustomer.name)) {
            const updatedCustomer = await getJson('/customers/' + customerId, {
              method: 'PATCH',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({
                name: name || selectedCustomer.name,
                phone,
                businessId: state.businessId
              })
            })
            state.customers = state.customers.map((customer) => customer.id === updatedCustomer.id ? updatedCustomer : customer)
          }
        }

        const appointmentId = state.editingAppointmentId
        const appointmentPath = appointmentId ? '/appointments/' + appointmentId : '/appointments'
        const appointmentPayload = {
            customerId,
            professionalId,
            serviceId,
            startAt: new Date(startAt).toISOString(),
            manualDepositPaid,
            manualDepositAmount,
            notes: notes || null
        }
        const submitAppointment = (forceOverride) => getJson(appointmentPath, {
          method: appointmentId ? 'PATCH' : 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ ...appointmentPayload, force: forceOverride })
        })
        try {
          await submitAppointment(force)
        } catch (error) {
          const writeConflicts = Array.isArray(error.body?.conflicts) ? error.body.conflicts : []
          const canRetryAsOverride = !force &&
            error.body?.code === 'APPOINTMENT_AVAILABILITY_CONFLICT' &&
            error.body?.forceable === true &&
            writeConflicts.length > 0
          if (!canRetryAsOverride) throw error
          const confirmedOverride = await confirmManualAppointmentOverride(
            writeConflicts,
            { startAt, professionalId, serviceId }
          )
          if (!confirmedOverride) return
          await submitAppointment(true)
        }

        closeAppointmentDialog()
        await loadAgenda()
        if (state.selected) {
          await loadAppointments()
          renderAppointments()
        }
      } catch (error) {
        const suggestion = error.message.includes('horario') || error.message.includes('disponible') || error.message.includes('bloqueado')
          ? ' Podes marcar Turno excepcional si decidiste forzarlo manualmente.'
          : ''
        els.appointmentFeedback.textContent = error.message + suggestion
      } finally {
        setButtonLoading(els.appointmentSubmit, false)
      }
    }

    async function deleteManualAppointment() {
      const appointmentId = state.editingAppointmentId
      if (!appointmentId) return
      if (!canCancelAppointments()) {
        els.appointmentFeedback.textContent = 'No tenes permiso para cancelar turnos.'
        return
      }
      if (!await requestCrmConfirmation('¿Querés eliminar este turno de la agenda?')) return

      if (!setButtonLoading(els.appointmentDelete, true, 'Eliminando...')) return
      try {
        await getJson('/appointments/' + appointmentId, {
          method: 'DELETE'
        })
        closeAppointmentDialog()
        await loadAgenda()
        if (state.selected) {
          await loadAppointments()
          renderAppointments()
        }
      } catch (error) {
        els.appointmentFeedback.textContent = error.message
      } finally {
        setButtonLoading(els.appointmentDelete, false)
      }
    }

    async function toggleManualAppointmentNoShow() {
      const appointmentId = state.editingAppointmentId
      if (!appointmentId) return
      if (!canCancelAppointments()) {
        els.appointmentFeedback.textContent = 'No tenes permiso para cambiar el estado del turno.'
        return
      }
      const appointment = state.agendaAppointments.find((item) => item.id === appointmentId)
      const isNoShow = appointment?.status === 'NO_SHOW'
      const nextStatus = isNoShow ? 'CONFIRMED' : 'NO_SHOW'
      if (!await requestCrmConfirmation(
        isNoShow ? '¿Querés quitar el estado ausente de este turno?' : '¿Querés marcar este turno como ausente?',
        { confirmLabel: isNoShow ? 'Sí, quitar estado' : 'Sí, marcar ausente', danger: false }
      )) return

      if (!setButtonLoading(els.appointmentNoShow, true, isNoShow ? 'Actualizando...' : 'Marcando...')) return
      try {
        await getJson('/appointments/' + appointmentId + '/status', {
          method: 'PATCH',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            status: nextStatus
          })
        })
        closeAppointmentDialog()
        await loadAgenda()
        if (state.selected) {
          await loadAppointments()
          renderAppointments()
        }
        if (els.appShell.dataset.section === 'reports') {
          await loadReports()
        }
      } catch (error) {
        els.appointmentFeedback.textContent = error.message
      } finally {
        setButtonLoading(els.appointmentNoShow, false)
      }
    }

