    async function simulateCampaign(campaign) {
      state.campaignSimulationLoading[campaign.id] = true
      renderCampaignDetail()
      try {
        const run = await getJson('/campaigns/' + campaign.id + '/simulate', { method: 'POST' })
        state.campaignSimulations[campaign.id] = run
        await loadCampaignAudience(campaign.id)
      } finally {
        state.campaignSimulationLoading[campaign.id] = false
        if (state.selectedCampaignId === campaign.id) renderCampaignDetail()
      }
    }

    async function syncCampaignTemplate(campaign) {
      const updated = await getJson('/campaigns/' + campaign.id + '/template/sync', { method: 'POST' })
      const index = state.campaigns.findIndex((item) => item.id === updated.id)
      if (index >= 0) state.campaigns[index] = updated
      renderCampaigns()
    }

    async function startManualCampaignExecution(campaign) {
      const execution = await getJson('/campaigns/' + campaign.id + '/manual-executions', { method: 'POST' })
      state.campaignManualExecutions[campaign.id] = execution
      state.campaignDetailTab = 'recipients'
      renderCampaignDetail()
    }

    async function updateManualCampaignRecipient(campaign, recipientId, status) {
      for (const button of els.campaignDetailPanel.querySelectorAll('[data-manual-recipient-action]')) button.disabled = true
      try {
        const execution = await getJson('/campaigns/' + campaign.id + '/manual-executions/' + state.campaignManualExecutions[campaign.id].id + '/recipients/' + recipientId, {
          method: 'PATCH',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ status, skipReason: status === 'SKIPPED' ? 'Omitido por el operador' : null })
        })
        state.campaignManualExecutions[campaign.id] = execution
        if (status === 'SENT') {
          state.campaignDeliveries[campaign.id] = await getJson('/campaigns/' + campaign.id + '/deliveries')
        }
        renderCampaignDetail()
      } catch (error) {
        const existing = els.campaignDetailPanel.querySelector('[data-campaign-inline-error]')
        if (existing) existing.remove()
        els.campaignDetailPanel.querySelector('.campaign-detail-header')?.insertAdjacentHTML('afterend', '<div class="campaign-rule-note" data-campaign-inline-error>' + escapeHtml(error.message) + '</div>')
      }
    }

    async function handleCampaignDetailAction(event) {
      const manualOpen = event.target.closest('[data-manual-open]')
      if (manualOpen) {
        const campaign = state.campaigns.find((item) => item.id === state.selectedCampaignId)
        if (campaign) void updateManualCampaignRecipient(campaign, manualOpen.dataset.manualRecipientId, 'OPENED')
        return
      }
      const manualRecipientAction = event.target.closest('[data-manual-recipient-action]')
      if (manualRecipientAction) {
        const campaign = state.campaigns.find((item) => item.id === state.selectedCampaignId)
        if (campaign) await updateManualCampaignRecipient(campaign, manualRecipientAction.dataset.manualRecipientId, manualRecipientAction.dataset.manualRecipientAction)
        return
      }
      const tab = event.target.closest('[data-campaign-tab]')
      if (tab) {
        state.campaignDetailTab = tab.dataset.campaignTab
        renderCampaignDetail()
        return
      }
      const button = event.target.closest('[data-campaign-action]')
      if (!button) return
      const campaign = state.campaigns.find((item) => item.id === state.selectedCampaignId)
      if (!campaign) return

      try {
        if (button.dataset.campaignAction === 'simulate') await simulateCampaign(campaign)
        if (button.dataset.campaignAction === 'manual-start') await startManualCampaignExecution(campaign)
        if (button.dataset.campaignAction === 'process-automated') {
          button.disabled = true
          button.textContent = 'Procesando...'
          const result = await getJson('/campaigns/' + campaign.id + '/process-automated', { method: 'POST' })
          await loadCampaignDeliveries(campaign.id)
          await loadCampaignSimulation(campaign.id)
          await loadCampaigns()
          els.campaignDetailPanel.querySelector('.campaign-detail-header')?.insertAdjacentHTML('afterend', '<div class="campaign-rule-note" data-campaign-inline-error>Procesado: ' + result.sent + ' enviados · ' + result.failed + ' fallidos.</div>')
          return
        }
        if (button.dataset.campaignAction === 'template-sync') await syncCampaignTemplate(campaign)
        if (button.dataset.campaignAction === 'edit') openCampaignDialog(campaign)
        if (button.dataset.campaignAction === 'toggle') await updateCampaignStatus(campaign)
        if (button.dataset.campaignAction === 'duplicate') await duplicateCampaign(campaign)
        if (button.dataset.campaignAction === 'delete') deleteCampaign(campaign)
      } catch (error) {
        const existing = els.campaignDetailPanel.querySelector('[data-campaign-inline-error]')
        if (existing) existing.remove()
        els.campaignDetailPanel.querySelector('.campaign-detail-header')?.insertAdjacentHTML('afterend', '<div class="campaign-rule-note" data-campaign-inline-error>' + escapeHtml(error.message) + '</div>')
      }
    }

    function setSection(section) {
      els.appShell.dataset.section = section
      document.body.dataset.currentSection = section
      const mobileTitle = document.getElementById('mobile-current-section-title')
      if (mobileTitle) {
        const labels = {
          accounts: 'Cuentas',
          conversations: 'Conversaciones',
          agenda: 'Agenda',
          customers: 'Clientes',
          professionals: 'Profesionales',
          services: 'Servicios',
          campaigns: 'Marketing',
          reports: 'Reportes',
          settings: 'Ajustes'
        }
        mobileTitle.textContent = labels[section] || 'Weex'
      }
      const buttons = document.querySelectorAll('.workspace-nav button[data-nav-section]')
      buttons.forEach((button) => {
        const isSection = button.dataset.navSection === section
        const isMarketingSubitem = section === 'campaigns' && button.closest('.nav-subitems') && button.dataset.marketingNav !== state.marketingView
        button.classList.toggle('active', isSection && !isMarketingSubitem)
      })
      document.querySelectorAll('[data-mobile-section]').forEach((button) => {
        button.classList.toggle('active', button.dataset.mobileSection === section)
      })

      if (section === 'agenda') {
        renderAgenda()
        loadAgenda().catch((error) => {
          els.agendaGridWrap.innerHTML = '<div class="error">' + escapeHtml(error.message) + '</div>'
        })
      }

      if (section === 'customers') {
        loadCustomerOverview().catch(() => {})
      }

      if (section === 'accounts') {
        loadManagedAccounts().catch(renderManagedAccountsLoadError)
      }

      if (section === 'professionals') {
        ensureProfessionalMedia().catch((error) => showCrmToast(error.message, 'error'))
        refreshScheduleBlockImpactPanel().catch((error) => showCrmToast(error.message, 'error'))
      }

      if (section === 'services') {
        ensureServiceMedia().catch((error) => showCrmToast(error.message, 'error'))
      }

      if (section === 'reports') {
        loadReports().catch((error) => {
          els.reportStatusBars.innerHTML = '<div class="error">' + escapeHtml(error.message) + '</div>'
        })
      }

      if (section === 'campaigns' && !state.campaignsLoaded) {
        loadCampaigns()
      }
      if (section === 'campaigns') setMarketingView(state.marketingView)
      if (section === 'campaigns' && !state.templatesLoaded) loadWhatsappTemplates()
      if (section === 'settings') {
        setSettingsView(state.settingsView)
        ensureBusinessMedia().catch((error) => showCrmToast(error.message, 'error'))
      }
      if (section === 'conversations' && isMobile()) setMobileView('inbox')
      closeMobileDrawer()
    }

    function startOfWeek(date) {
      const copy = startOfDay(date)
      copy.setDate(copy.getDate() - copy.getDay())
      return copy
    }

    function startOfMondayWeek(date) {
      const copy = startOfDay(date)
      const offset = (copy.getDay() + 6) % 7
      copy.setDate(copy.getDate() - offset)
      return copy
    }

    function startOfDay(date) {
      return new Date(date.getFullYear(), date.getMonth(), date.getDate())
    }

    function addDays(date, days) {
      const copy = new Date(date)
      copy.setDate(copy.getDate() + days)
      return copy
    }

    function addMinutes(date, minutes) {
      return new Date(date.getTime() + minutes * 60 * 1000)
    }

    function isDateInRange(date, start, end) {
      const value = startOfDay(date).getTime()
      return value >= startOfDay(start).getTime() && value < startOfDay(end).getTime()
    }

    function dateKey(date) {
      const year = date.getFullYear()
      const month = String(date.getMonth() + 1).padStart(2, '0')
      const day = String(date.getDate()).padStart(2, '0')
      return year + '-' + month + '-' + day
    }

    function toDatetimeLocalValue(value) {
      const date = value instanceof Date ? value : new Date(value)
      if (Number.isNaN(date.getTime())) return ''
      const year = date.getFullYear()
      const month = String(date.getMonth() + 1).padStart(2, '0')
      const day = String(date.getDate()).padStart(2, '0')
      const hour = String(date.getHours()).padStart(2, '0')
      const minute = String(date.getMinutes()).padStart(2, '0')
      return year + '-' + month + '-' + day + 'T' + hour + ':' + minute
    }

    function parseDateKey(value) {
      const [year, month, day] = String(value).split('-').map(Number)
      return new Date(year, month - 1, day)
    }

    function timeToMinutes(value) {
      const [hours, minutes] = String(value || '00:00').split(':').map(Number)
      return hours * 60 + minutes
    }

    function formatMinuteLabel(minute) {
      const hours = Math.floor(minute / 60)
      const minutes = minute % 60
      return String(hours).padStart(2, '0') + ':' + String(minutes).padStart(2, '0')
    }

    function formatTimeOnly(date) {
      return new Intl.DateTimeFormat('es-AR', {
        hour: '2-digit',
        minute: '2-digit'
      }).format(date)
    }

    function formatAgendaRange(start, end) {
      const monthFormatter = new Intl.DateTimeFormat('es-AR', { month: 'long' })
      const startMonth = monthFormatter.format(start)
      const endMonth = monthFormatter.format(end)
      if (start.getMonth() === end.getMonth() && start.getFullYear() === end.getFullYear()) {
        return start.getDate() + ' al ' + end.getDate() + ' de ' + endMonth + ' de ' + end.getFullYear()
      }

      if (start.getFullYear() === end.getFullYear()) {
        return start.getDate() + ' de ' + startMonth + ' al ' + end.getDate() + ' de ' + endMonth + ' de ' + end.getFullYear()
      }

      return start.getDate() + ' de ' + startMonth + ' de ' + start.getFullYear() + ' al ' + end.getDate() + ' de ' + endMonth + ' de ' + end.getFullYear()
    }

    function formatAgendaDayHeader(date) {
      const weekday = ['Dom', 'Lun', 'Mar', 'Mi&eacute;', 'Jue', 'Vie', 'S&aacute;b'][date.getDay()]
      return weekday + ' ' + date.getDate() + '/' + (date.getMonth() + 1)
    }

    function formatAgendaMobileDay(date) {
      return new Intl.DateTimeFormat('es-AR', {
        weekday: 'long',
        day: 'numeric',
        month: 'short'
      }).format(date)
    }

    function formatAgendaMobileTitle(date) {
      const options = date.getFullYear() === new Date().getFullYear()
        ? { month: 'long' }
        : { month: 'short', year: 'numeric' }
      return new Intl.DateTimeFormat('es-AR', options).format(date)
    }

    async function saveServiceCategory() {
      if (!state.businessId) {
        els.serviceCategoryFeedback.textContent = 'No encontré un negocio cargado.'
        return
      }
      const id = els.serviceCategoryId.value
      const name = els.serviceCategoryName.value.trim()
      const aliases = els.serviceCategoryAliases.value
        .split(',')
        .map((alias) => alias.trim())
        .filter(Boolean)
      const adviceEnabled = els.serviceCategoryAdviceEnabled.checked
      if (!name) {
        els.serviceCategoryFeedback.textContent = 'Escribí el nombre de la categoría.'
        els.serviceCategoryName.focus()
        return
      }

      if (!setButtonLoading(els.serviceCategorySave, true, id ? 'Guardando...' : 'Agregando...')) return
      try {
        const category = await getJson(id ? '/service-categories/' + id : '/service-categories', {
          method: id ? 'PATCH' : 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            businessId: state.businessId,
            name,
            aliases,
            adviceEnabled
          })
        })
        const shouldSelectCreatedCategory =
          !id &&
          els.serviceCategoryDialog.dataset.selectCreated === 'true' &&
          category?.id
        await reloadServiceCatalog()
        if (shouldSelectCreatedCategory) {
          els.serviceCategory.value = category.id
          els.serviceCategory.dataset.lastValue = category.id
        }
        closeServiceCategoryDialog()
        els.serviceFeedback.textContent = id ? 'Categoría actualizada.' : 'Categoría creada.'
      } catch (error) {
        els.serviceCategoryFeedback.textContent = error.message
      } finally {
        setButtonLoading(els.serviceCategorySave, false)
      }
    }

    function openServiceCategoryDialog({ selectCreated = false } = {}) {
      resetServiceCategoryForm()
      els.serviceCategoryFeedback.textContent = ''
      els.serviceCategoryDialog.dataset.selectCreated = selectCreated ? 'true' : 'false'
      els.serviceCategoryDialog.hidden = false
      requestAnimationFrame(() => els.serviceCategoryName.focus())
    }

    function closeServiceCategoryDialog() {
      els.serviceCategoryDialog.hidden = true
      els.serviceCategoryDialog.dataset.selectCreated = 'false'
      resetServiceCategoryForm()
      els.serviceCategoryFeedback.textContent = ''
    }

    function editServiceCategory(id) {
      const category = state.serviceCategories.find((item) => item.id === id)
      if (!category) return
      els.serviceCategoryId.value = category.id
      els.serviceCategoryName.value = category.name
      els.serviceCategoryAliases.value = (category.aliases || []).map((alias) => alias.name).join(', ')
      els.serviceCategoryAdviceEnabled.checked = category.adviceEnabled === true
      els.serviceCategorySave.textContent = 'Guardar'
      els.serviceCategoryCancel.hidden = false
      els.serviceCategoryDialogTitle.textContent = 'Editar categoría'
      els.serviceCategoryFeedback.textContent = ''
      els.serviceCategoryName.focus()
    }

    async function deleteServiceCategory(id) {
      const category = state.serviceCategories.find((item) => item.id === id)
      if (!category) return
      const serviceCount = Number(category._count?.services || 0)
      const categoryMessage = serviceCount > 0
        ? '¿Querés eliminar la categoría ' + category.name + '? Sus ' + serviceCount + ' servicios se conservarán sin categoría.'
        : '¿Querés eliminar la categoría ' + category.name + '?'
      if (!await requestCrmConfirmation(categoryMessage)) return
      try {
        await getJson('/service-categories/' + id, { method: 'DELETE' })
        resetServiceCategoryForm()
        await reloadServiceCatalog()
        els.serviceCategoryFeedback.textContent = 'Categoría eliminada.'
      } catch (error) {
        els.serviceCategoryFeedback.textContent = error.message
      }
    }

    function resetServiceCategoryForm() {
      els.serviceCategoryId.value = ''
      els.serviceCategoryName.value = ''
      els.serviceCategoryAliases.value = ''
      els.serviceCategoryAdviceEnabled.checked = false
      els.serviceCategorySave.textContent = 'Agregar'
      els.serviceCategoryCancel.hidden = true
      els.serviceCategoryDialogTitle.textContent = 'Agregar categoría'
    }

